/* =========================================================================
 * MOCK EXAM — 2 sets, structurally separate from QUIZ (no overlap)
 * ========================================================================= */
_mock.push(
  { ja: "模試A（基礎〜標準）", en: "Mock A (Basic–Standard)", questions: [
    { id: "mA1", diff: 1, q: { ja: "限界利益率30%、固定費900万のBEP売上高は。", en: "CM ratio 30%, fixed ¥9M. BEP sales?" },
      choices: [{ ja: "3,000万円", en: "¥30M" }, { ja: "2,700万円", en: "¥27M" }, { ja: "1,200万円", en: "¥12M" }, { ja: "300万円", en: "¥3M" }], ans: 0,
      exp: { ja: "900万÷0.30＝3,000万円。", en: "9M ÷ 0.30 = ¥30M." } },
    { id: "mA2", diff: 2, q: { ja: "全部原価計算で在庫が増加した期、直接原価計算と比べ営業利益は。", en: "When inventory rises, absorption vs. variable costing profit is?" },
      choices: [{ ja: "全部原価計算の方が大きい", en: "Higher under absorption" }, { ja: "直接原価計算の方が大きい", en: "Higher under variable" }, { ja: "同額", en: "Equal" }, { ja: "常にゼロ", en: "Always zero" }], ans: 0,
      exp: { ja: "在庫増で固定費が在庫に繰延べられ、全部原価計算の利益が大きくなる。", en: "Rising inventory defers fixed cost into stock, raising absorption profit." } },
    { id: "mA3", diff: 1, q: { ja: "ABCで配賦基準となるものはどれか。", en: "What is the allocation basis in ABC?" },
      choices: [{ ja: "コストドライバー", en: "Cost driver" }, { ja: "売上総利益", en: "Gross profit" }, { ja: "総資産", en: "Total assets" }, { ja: "株価", en: "Stock price" }], ans: 0,
      exp: { ja: "ABCは活動量を測るコストドライバーで間接費を配賦する。", en: "ABC allocates overhead via activity-measuring cost drivers." } },
    { id: "mA4", diff: 2, q: { ja: "埋没原価の扱いとして正しいのは。", en: "Correct treatment of a sunk cost?" },
      choices: [{ ja: "意思決定で無視する", en: "Ignore it" }, { ja: "必ず回収する", en: "Recover it" }, { ja: "全額費用化する", en: "Expense fully now" }, { ja: "限界利益に加える", en: "Add to CM" }], ans: 0,
      exp: { ja: "埋没原価は変更不能で将来意思決定に無関連。", en: "Sunk costs are unchangeable and irrelevant to future decisions." } },
    { id: "mA5", diff: 2, q: { ja: "CCCが短いほど示すものは。", en: "A shorter CCC indicates?" },
      choices: [{ ja: "運転資金効率が良い", en: "Better working-capital efficiency" }, { ja: "負債が多い", en: "More debt" }, { ja: "粗利が低い", en: "Lower margin" }, { ja: "在庫が多い", en: "More inventory" }], ans: 0,
      exp: { ja: "CCCが短い＝現金回収が速く運転資金効率が高い。", en: "Shorter CCC means faster cash recovery and better working-capital efficiency." } },
    {"id":"mA6","diff":2,"q":{"ja":"限界利益率40%、固定費1,200万のとき、営業利益300万を得る売上高は。","en":"CM ratio 40%, fixed ¥12M. Sales for ¥3M operating profit?"},"choices":[{"ja":"3,750万円","en":"¥37.5M"},{"ja":"3,000万円","en":"¥30M"},{"ja":"1,500万円","en":"¥15M"},{"ja":"4,500万円","en":"¥45M"}],"ans":0,"exp":{"ja":"(1,200+300)÷0.40＝3,750万円。","en":"(12M + 3M) ÷ 0.40 = ¥37.5M."}},{"id":"mA7","diff":1,"q":{"ja":"次のうち変動費に分類されるのは。","en":"Which is a variable cost?"},"choices":[{"ja":"出来高に応じた材料費","en":"Output-based material cost"},{"ja":"工場の賃借料","en":"Factory rent"},{"ja":"管理職の固定給","en":"Manager salary"},{"ja":"定額減価償却費","en":"SL depreciation"}],"ans":0,"exp":{"ja":"材料費は操業度に比例して動く変動費。賃借料・固定給・定額償却は固定費。","en":"Material cost scales with activity (variable); rent, salaries, and SL depreciation are fixed."}},{"id":"mA8","diff":2,"q":{"ja":"貢献利益方式P/Lで固定製造原価はどう扱われるか。","en":"How is fixed mfg overhead treated in a contribution-margin P/L?"},"choices":[{"ja":"期間費用として一括控除","en":"Deducted as a period cost"},{"ja":"製品原価に算入し在庫へ","en":"Capitalized into inventory"},{"ja":"売上に加算","en":"Added to sales"},{"ja":"無視する","en":"Ignored"}],"ans":0,"exp":{"ja":"直接原価計算では固定製造原価を期間費用として扱い、限界利益の下で一括控除する。","en":"Under direct costing, fixed mfg overhead is a period cost, deducted below contribution margin."}},{"id":"mA9","diff":2,"q":{"ja":"標準原価の価格差異が不利となる典型要因は。","en":"Typical cause of an unfavorable price variance?"},"choices":[{"ja":"購入単価が標準より高かった","en":"Purchase rate above standard"},{"ja":"歩留りが改善した","en":"Yield improved"},{"ja":"作業時間が短縮した","en":"Hours fell"},{"ja":"売上が増えた","en":"Sales rose"}],"ans":0,"exp":{"ja":"価格差異は(標準@−実際@)×実際数量。実際単価が標準より高いと不利差異。","en":"Price variance = (std − actual rate) × actual qty; a higher actual rate is unfavorable."}},{"id":"mA10","diff":1,"q":{"ja":"予算編成で『トップダウン』が指すものは。","en":"What does 'top-down' budgeting mean?"},"choices":[{"ja":"経営層が目標を提示し各部門へ展開","en":"Leadership sets targets, cascaded down"},{"ja":"現場が一から積み上げる","en":"Floor builds from scratch"},{"ja":"前年実績をそのまま使う","en":"Copy last year"},{"ja":"競合に合わせる","en":"Match competitors"}],"ans":0,"exp":{"ja":"トップダウンは経営層が全社目標を示し各部門へ割り当てる方式。対するボトムアップは現場積上げ。","en":"Top-down: leadership sets company targets allocated to units; bottom-up builds from the floor."}}
  ]},
  { ja: "模試B（標準〜応用）", en: "Mock B (Standard–Advanced)", questions: [
    { id: "mB1", diff: 3, q: { ja: "EVAが正となる条件は。", en: "When is EVA positive?" },
      choices: [{ ja: "ROIC＞WACC", en: "ROIC > WACC" }, { ja: "売上増", en: "Sales grow" }, { ja: "負債減", en: "Debt falls" }, { ja: "黒字", en: "Net income positive" }], ans: 0,
      exp: { ja: "EVA＝投下資本×(ROIC−WACC)。資本コスト超で正。", en: "EVA = capital × (ROIC − WACC); positive only above the cost of capital." } },
    { id: "mB2", diff: 3, q: { ja: "ボトルネック下の製品優先順位の基準は。", en: "Priority criterion under a bottleneck?" },
      choices: [{ ja: "制約資源単位あたり限界利益", en: "CM per unit of the constraint" }, { ja: "製品単位あたり売上", en: "Sales per unit" }, { ja: "固定費配賦額", en: "Fixed cost allocated" }, { ja: "在庫回転率", en: "Inventory turnover" }], ans: 0,
      exp: { ja: "制約1単位あたり限界利益が最大の製品を優先する。", en: "Prioritize the highest CM per unit of the bottleneck." } },
    { id: "mB3", diff: 2, q: { ja: "変動予算の比較対象は。", en: "A flexible budget is compared at?" },
      choices: [{ ja: "実際操業度ベースの予算", en: "Budget at actual activity" }, { ja: "固定金額", en: "A fixed amount" }, { ja: "前年実績", en: "Prior-year actual" }, { ja: "競合の予算", en: "Competitor budget" }], ans: 0,
      exp: { ja: "変動予算は実際操業度に組み替えた予算と実績を比較する。", en: "A flexible budget compares actuals to a budget flexed to actual activity." } },
    { id: "mB4", diff: 3, q: { ja: "3表モデルの循環参照が起きる代表箇所は。", en: "Typical circular reference in a 3-statement model?" },
      choices: [{ ja: "支払利息と負債残高", en: "Interest and debt balance" }, { ja: "売上と数量", en: "Sales and volume" }, { ja: "定額償却", en: "SL depreciation" }, { ja: "税率", en: "Tax rate" }], ans: 0,
      exp: { ja: "利息↔負債↔現金の相互依存で循環参照が生じる。", en: "Interest ↔ debt ↔ cash interdependence creates circularity." } },
    { id: "mB5", diff: 2, q: { ja: "ROEのデュポン分解に含まれないのは。", en: "NOT a DuPont component of ROE?" },
      choices: [{ ja: "流動比率", en: "Current ratio" }, { ja: "純利益率", en: "Net margin" }, { ja: "総資産回転率", en: "Asset turnover" }, { ja: "財務レバレッジ", en: "Leverage" }], ans: 0,
      exp: { ja: "ROE＝純利益率×総資産回転率×レバレッジ。流動比率は含まない。", en: "ROE = net margin × asset turnover × leverage; current ratio is not part of it." } },
    {"id":"mB6","diff":3,"q":{"ja":"遊休能力がない状態で特別注文を受ける際、必ず考慮すべきは。","en":"With NO idle capacity, what must a special order include?"},"choices":[{"ja":"通常販売を諦める機会費用","en":"Opportunity cost of lost regular sales"},{"ja":"埋没した過去原価","en":"Past sunk cost"},{"ja":"配賦済み固定費","en":"Already-allocated fixed cost"},{"ja":"減価償却累計額","en":"Accumulated depreciation"}],"ans":0,"exp":{"ja":"能力に余裕がなければ、特別注文を受けると通常販売を失う。その機会費用を関連原価に加える。","en":"Without spare capacity, taking the order sacrifices regular sales; add that opportunity cost as relevant."}},{"id":"mB7","diff":3,"q":{"ja":"ROICツリーで『投下資本回転率』を高める打ち手は。","en":"Which lever raises capital turnover in the ROIC tree?"},"choices":[{"ja":"運転資本(在庫・売掛)の圧縮","en":"Shrink working capital (inventory, AR)"},{"ja":"値引きの拡大","en":"Deepen discounts"},{"ja":"固定費の増額","en":"Raise fixed cost"},{"ja":"配当の増額","en":"Raise dividends"}],"ans":0,"exp":{"ja":"回転率＝売上÷投下資本。運転資本や遊休設備を圧縮すれば分母が下がり回転率が上がる。","en":"Turnover = sales ÷ invested capital; cutting working capital or idle assets lowers the denominator."}},{"id":"mB8","diff":2,"q":{"ja":"原価企画(ターゲットコスティング)で許容原価を求める式は。","en":"Allowable cost formula in target costing?"},"choices":[{"ja":"目標価格 − 目標利益","en":"Target price − target profit"},{"ja":"標準原価 + 利益","en":"Standard cost + profit"},{"ja":"実際原価 × 倍率","en":"Actual cost × markup"},{"ja":"売上 − 税金","en":"Sales − tax"}],"ans":0,"exp":{"ja":"許容原価＝目標価格−目標利益。市場が決める価格から逆算し、設計段階で原価を作り込む。","en":"Allowable cost = target price − target profit; back-solved from a market price and built in at design."}},{"id":"mB9","diff":3,"q":{"ja":"ローリング予測が固定年次予算より優れる点は。","en":"An advantage of rolling forecasts over a fixed annual budget?"},"choices":[{"ja":"常に先12〜18カ月の視界を保つ","en":"Always keeps a 12–18 month horizon"},{"ja":"更新が年1回で済む","en":"Updated only yearly"},{"ja":"前提を固定できる","en":"Locks assumptions"},{"ja":"予算消化を促す","en":"Encourages spend-down"}],"ans":0,"exp":{"ja":"ローリング予測は毎期更新し常に先12〜18カ月を見るため、期末に視界が狭まる固定予算の弱点を補う。","en":"Rolling forecasts update each period and keep a 12–18 month view, offsetting the fixed budget's shrinking horizon."}},{"id":"mB10","diff":2,"q":{"ja":"先行指標(leading KPI)の例として適切なのは。","en":"Which is a leading KPI?"},"choices":[{"ja":"商談パイプライン件数","en":"Sales pipeline count"},{"ja":"当期売上高","en":"This period's revenue"},{"ja":"確定した営業利益","en":"Booked operating profit"},{"ja":"期末の市場シェア","en":"Year-end market share"}],"ans":0,"exp":{"ja":"先行指標は結果が出る前に動かせる原因系。商談数は将来売上の先行シグナル。売上・利益・シェアは遅行指標。","en":"Leading KPIs are actionable causes before results land; pipeline leads future sales. Revenue, profit, and share are lagging."}}
  ]},
  {"ja":"模試C（横断・実務）","en":"Mock C (Cross-topic / Applied)","questions":[{"id":"mC1","diff":2,"q":{"ja":"売上6,000万、変動費3,600万、固定費1,800万。営業利益は。","en":"Sales ¥60M, VC ¥36M, fixed ¥18M. Operating profit?"},"choices":[{"ja":"600万円","en":"¥6M"},{"ja":"2,400万円","en":"¥24M"},{"ja":"1,800万円","en":"¥18M"},{"ja":"3,000万円","en":"¥30M"}],"ans":0,"exp":{"ja":"限界利益＝6,000−3,600＝2,400万。営業利益＝2,400−1,800＝600万。","en":"CM = 60−36 = 24M; operating profit = 24 − 18 = ¥6M."}},{"id":"mC2","diff":3,"q":{"ja":"上記で固定費が大きいほど高くなる指標は。","en":"Which rises with higher fixed cost (same case)?"},"choices":[{"ja":"経営レバレッジ係数(DOL)","en":"Degree of operating leverage"},{"ja":"限界利益率","en":"CM ratio"},{"ja":"変動費率","en":"Variable cost ratio"},{"ja":"税率","en":"Tax rate"}],"ans":0,"exp":{"ja":"DOL＝限界利益÷営業利益。固定費が大きいほど営業利益が小さくDOLが高い＝利益の感応度大。","en":"DOL = CM ÷ operating profit; more fixed cost shrinks operating profit, raising DOL and profit sensitivity."}},{"id":"mC3","diff":2,"q":{"ja":"製品Aの限界利益率50%、製品Bは30%。固定費一定で利益を最大化するには。","en":"Product A CM 50%, B 30%, fixed constant. To maximize profit?"},"choices":[{"ja":"高限界利益率のAへミックスシフト","en":"Shift mix toward high-CM A"},{"ja":"Bを増やす","en":"Sell more B"},{"ja":"両方同率で減らす","en":"Cut both equally"},{"ja":"価格を下げる","en":"Cut prices"}],"ans":0,"exp":{"ja":"固定費一定なら、限界利益率の高い製品の構成比を高めるほど全体の限界利益＝利益が増える。","en":"With fixed cost constant, shifting mix to higher-CM products raises total contribution and profit."}},{"id":"mC4","diff":3,"q":{"ja":"労務費の作業時間差異が不利となる主因は。","en":"Main cause of an unfavorable labor efficiency variance?"},"choices":[{"ja":"実際作業時間が標準より長い","en":"Actual hours exceed standard"},{"ja":"賃率が下がった","en":"Wage rate fell"},{"ja":"材料単価が上昇","en":"Material rate rose"},{"ja":"売上が増えた","en":"Sales rose"}],"ans":0,"exp":{"ja":"作業時間差異＝(標準時間−実際時間)×標準賃率。実際時間が長いと不利。生産性・段取りが要因。","en":"Efficiency variance = (std − actual hours) × std rate; longer actual hours are unfavorable — productivity/setup driven."}},{"id":"mC5","diff":2,"q":{"ja":"ABCが従来配賦より精度を増す典型的状況は。","en":"When does ABC beat traditional allocation most?"},"choices":[{"ja":"間接費が大きく多品種少量生産","en":"High overhead, high-variety low-volume"},{"ja":"間接費がほぼゼロ","en":"Almost no overhead"},{"ja":"単一製品の大量生産","en":"Single-product mass production"},{"ja":"在庫がない","en":"No inventory"}],"ans":0,"exp":{"ja":"間接費が大きく品種が多いほど単一基準配賦の歪みが大きく、ABCの活動基準が効く。","en":"The larger the overhead and product variety, the greater the single-base distortion, so ABC helps most."}},{"id":"mC6","diff":3,"q":{"ja":"NOPAT 600、投下資本5,000、WACC 10%のEVAは。","en":"NOPAT 600, invested capital 5,000, WACC 10%. EVA?"},"choices":[{"ja":"+100","en":"+100"},{"ja":"+600","en":"+600"},{"ja":"−500","en":"−500"},{"ja":"0","en":"0"}],"ans":0,"exp":{"ja":"資本コスト＝5,000×10%＝500。EVA＝600−500＝+100（価値創造）。","en":"Capital charge = 5,000×10% = 500; EVA = 600 − 500 = +100 (value creating)."}},{"id":"mC7","diff":2,"q":{"ja":"予実の数量差異を求める式は。","en":"Formula for the volume (quantity) variance?"},"choices":[{"ja":"(実際数量−予算数量)×予算単価","en":"(actual − budget qty) × budget price"},{"ja":"(実際単価−予算単価)×実際数量","en":"(actual − budget price) × actual qty"},{"ja":"実際売上−予算売上","en":"Actual − budget sales"},{"ja":"売上÷数量","en":"Sales ÷ qty"}],"ans":0,"exp":{"ja":"数量差異＝(実際数量−予算数量)×予算単価。価格差異は(実際単価−予算単価)×実際数量。","en":"Volume variance = (actual − budget qty) × budget price; price variance = (actual − budget price) × actual qty."}},{"id":"mC8","diff":3,"q":{"ja":"制約資源(ボトルネック)が1時間あたり、製品X限界利益1,200円/時、製品Y 900円/時。優先すべきは。","en":"Per bottleneck hour: X earns ¥1,200 CM/hr, Y ¥900/hr. Prioritize?"},"choices":[{"ja":"製品X","en":"Product X"},{"ja":"製品Y","en":"Product Y"},{"ja":"どちらでも同じ","en":"Indifferent"},{"ja":"両方停止","en":"Stop both"}],"ans":0,"exp":{"ja":"制約1単位(時間)あたり限界利益が高いXを優先するとボトルネックの利益貢献が最大化する。","en":"Prioritize X with the higher CM per unit of the constraint to maximize the bottleneck's profit contribution."}},{"id":"mC9","diff":2,"q":{"ja":"ゼロベース予算(ZBB)の特徴は。","en":"A feature of zero-based budgeting (ZBB)?"},"choices":[{"ja":"全費用をゼロから正当化","en":"Justify every cost from zero"},{"ja":"前年実績に一律加算","en":"Add a flat % to last year"},{"ja":"予算を作らない","en":"No budget at all"},{"ja":"売上のみ管理","en":"Track only sales"}],"ans":0,"exp":{"ja":"ZBBは前年を前提とせず、各費用をゼロから必要性を正当化して積み上げる。費用見直しに有効だが負荷大。","en":"ZBB justifies each cost from zero rather than basing it on last year — effective for cost review but labor-intensive."}},{"id":"mC10","diff":3,"q":{"ja":"ROICがWACCを下回り続ける事業についての評価は。","en":"A business with ROIC persistently below WACC is?"},"choices":[{"ja":"価値を破壊している(再構築/撤退の検討)","en":"Destroying value (consider restructure/exit)"},{"ja":"必ず優良事業","en":"Always excellent"},{"ja":"黒字なら問題なし","en":"Fine if profitable"},{"ja":"成長すれば自動解決","en":"Growth auto-fixes it"}],"ans":0,"exp":{"ja":"ROIC<WACCは資本コストを賄えず価値破壊。成長は損失を拡大しうる。再構築・資本再配分・撤退を検討する。","en":"ROIC < WACC fails to cover the cost of capital — value destruction; growth can worsen it. Consider restructuring, reallocation, or exit."}}]},
);

