            q: { ja: "FASTstandardが掲げる要素でないのは。", en: "Which is NOT part of the FAST standard?" },
            ch: { ja: ["Fast(高速)", "Flexible", "Structured", "Transparent"], en: ["Fast (speed)", "Flexible", "Structured", "Transparent"] },
            a: 0,
