      {
        id: "cvpsim",
        kind: "sim",
        layout: "widget",
        title: {
          ja: "CVP分析 電卓（損益分岐点シミュレータ）",
          en: "CVP calculator (break-even simulator)"
        },
        sub: {
          ja: "販売単価・変動費・固定費・実際売上をスライダーで動かすと、BEP・貢献利益率・安全余裕率が即時に計算されます。",
          en: "Move the price / variable-cost / fixed-cost / actual-sales sliders for live BEP, contribution margin ratio, and margin of safety."
        },
        inputs: [
          {
            id: "price",
            label: {
              ja: "販売単価（円/個）",
              en: "Unit price"
            },
            min: 500,
            max: 3000,
            step: 100,
            default: 1000,
            unit: {
              ja: "円",
              en: ""
            }
          },
          {
            id: "variable",
            label: {
              ja: "変動費（円/個）",
              en: "Variable cost/unit"
            },
            min: 100,
            max: 2500,
            step: 100,
            default: 600,
            unit: {
              ja: "円",
              en: ""
            }
          },
          {
            id: "fixed",
            label: {
              ja: "固定費（円）",
              en: "Fixed cost"
            },
            min: 200000,
            max: 6000000,
            step: 100000,
            default: 1200000,
            unit: {
              ja: "円",
              en: ""
            }
          },
          {
            id: "actual",
            label: {
              ja: "実際売上高（円）",
              en: "Actual sales"
            },
            min: 1000000,
            max: 15000000,
            step: 500000,
            default: 5000000,
            unit: {
              ja: "円",
              en: ""
            }
          }
        ],
        outputs: [
          {
            label: {
              ja: "単位あたり貢献利益",
              en: "Contribution margin / unit"
            },
            unit: {
              ja: "円",
              en: ""
            },
            ramp: "cyan",
            calc: function (v) { return v.price - v.variable; }
          },
          {
            label: {
              ja: "貢献利益率",
              en: "Contribution margin ratio"
            },
            unit: {
              ja: "%",
              en: "%"
            },
            ramp: "cyan",
            calc: function (v) { if (v.price <= 0) return "—"; return Math.round((v.price - v.variable) / v.price * 1000) / 10; }
          },
          {
            label: {
              ja: "損益分岐点 販売量",
              en: "Break-even quantity"
            },
            unit: {
              ja: "個",
              en: "u"
            },
            ramp: "green",
            calc: function (v) { var cm = v.price - v.variable; if (cm <= 0) return "—"; return Math.round(v.fixed / cm); }
          },
          {
            label: {
              ja: "損益分岐点 売上高",
              en: "Break-even sales"
            },
            unit: {
              ja: "円",
              en: ""
            },
            ramp: "green",
            calc: function (v) { var cm = v.price - v.variable; if (cm <= 0) return "—"; return Math.round(v.fixed / cm) * v.price; }
          },
          {
            label: {
              ja: "安全余裕率",
              en: "Margin of safety ratio"
            },
            unit: {
              ja: "%",
              en: "%"
            },
            ramp: "amber",
            calc: function (v) { var cm = v.price - v.variable; if (cm <= 0 || v.actual <= 0) return "—"; var beps = Math.round(v.fixed / cm) * v.price; var m = (v.actual - beps) / v.actual * 100; return Math.round(m * 10) / 10; }
          },
          {
            label: {
              ja: "実際売上での営業利益",
              en: "Operating income at actual sales"
            },
            unit: {
              ja: "円",
              en: ""
            },
            ramp: "cyan",
            calc: function (v) { if (v.price <= 0) return "—"; var ratio = (v.price - v.variable) / v.price; return Math.round(v.actual * ratio - v.fixed); }
          }
        ]
      }
