// ===== 辞書検索の強化 =====
// 表記ゆれ吸収: 全角英数→半角・小文字化・長音/中黒/空白除去
function normalizeSearch(str) {
  if (!str) return "";
  return str
    .replace(/[Ａ-Ｚａ-ｚ０-９]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xFEE0)) // 全角英数→半角
    .toLowerCase()
    .replace(/[ー・\s\u3000]/g, ""); // 長音・中黒・半/全角スペース除去
}
// 略語・別名 → 検索対象に足す語（正規化前の素の文字列でOK、内部で正規化される）
const LEX_ALIASES = {
  "MoE": ["専門家混合", "mixture of experts", "モデル崩壊対策"],
  "MLA": ["潜在注意", "multi-head latent attention", "kvキャッシュ削減"],
  "GQA": ["grouped query attention", "kvキャッシュ"],
  "MQA": ["multi query attention"],
  "vLLM": ["pagedattention", "ページドアテンション"],
  "MCP": ["model context protocol", "モデルコンテキストプロトコル", "usb-c for ai"],
  "A2A": ["agent2agent", "エージェント間連携", "エージェント間"],
  "RAG": ["retrieval augmented generation", "検索拡張生成"],
  "GRPO": ["group relative policy optimization"],
  "DPO": ["direct preference optimization", "選好最適化"],
  "RLHF": ["人間フィードバック", "reinforcement learning from human feedback"],
  "RLAIF": ["aiフィードバック"],
  "RLVR": ["検証可能報酬", "verifiable rewards"],
  "LoRA": ["low rank adaptation", "peft", "アダプタ"],
  "SAE": ["sparse autoencoder", "スパースオートエンコーダ", "機構的解釈"],
  "SSM": ["状態空間モデル", "state space model", "mamba"],
  "SLM": ["小型言語モデル", "small language model", "エッジ推論"],
  "VLM": ["vision language model", "視覚言語モデル", "マルチモーダル"],
  "KV": ["kvキャッシュ", "key value cache"],
  "FP8": ["量子化", "浮動小数点8"],
  "INT4": ["量子化", "4bit"],
  "AWQ": ["activation aware weight quantization"],
  "GPTQ": ["量子化"],
  "TTFT": ["time to first token", "初動遅延", "プレフィル"],
  "SLO": ["service level objective", "エラーバジェット"],
  "CDC": ["change data capture", "変更捕捉"],
  "HITL": ["human in the loop", "人間参加", "承認"],
  "ASL": ["ai safety level", "ai安全性レベル", "責任あるスケーリング"],
  "RSP": ["responsible scaling policy", "責任あるスケーリング方針"],
  "ANN": ["approximate nearest neighbor", "近似最近傍", "hnsw"],
  "BPE": ["byte pair encoding", "トークン化"],
  "CoT": ["chain of thought", "思考連鎖", "推論"],
  "CRAG": ["corrective rag", "是正的rag"],
  "YaRN": ["ropeスケーリング", "文脈長拡張"],
  "EAGLE": ["投機的デコード", "speculative decoding"],
  "Medusa": ["投機的デコード", "speculative decoding"],
  "AIBOM": ["ai部品表", "bill of materials"],
  "TRiSM": ["trust risk security"],
  "ColBERT": ["遅延相互作用", "late interaction"],
};
// クエリを正規化し、エイリアスから追加の検索語を展開
function expandQuery(rawQuery) {
  const norm = normalizeSearch(rawQuery);
  const extra = [];
  const rawLower = rawQuery.trim().toLowerCase();
  for (const key in LEX_ALIASES) {
    if (key.toLowerCase() === rawLower || normalizeSearch(key) === norm) {
      LEX_ALIASES[key].forEach((a) => extra.push(normalizeSearch(a)));
    }
  }
  return { norm, extra };
}

function TabLexicon() {
  const lang = useLang();
  const { jump, setJump } = useJump();
  const ALL = "すべて";
  const cats = [ALL, "推論", "アルゴリズム", "学習", "RAG", "エージェント", "評価", "分散", "運用", "戦略", "概念"];
  const catKey = { "すべて": "lx_all", "推論": "lx_c_inference", "アルゴリズム": "lx_c_algo", "学習": "lx_c_training", "RAG": "lx_c_rag", "エージェント": "lx_c_agent", "評価": "lx_c_eval", "分散": "lx_c_distributed", "運用": "lx_c_ops", "戦略": "lx_c_strategy", "概念": "lx_c_concept" };
  const catLabel = (c) => t(lang, catKey[c] || "lx_all");
  const [cat, setCat] = useState(ALL);
  const [query, setQuery] = useState("");
  const [tier, setTier] = useState("all"); // all/prod/emerg/res
  const TIERS = [["all", "lx_tier_all"], ["prod", "lx_tier_prod"], ["emerg", "lx_tier_emerg"], ["res", "lx_tier_res"]];
  const tierMeta = { prod: { label: "lx_tier_prod", color: C.teal }, emerg: { label: "lx_tier_emerg", color: C.gold }, res: { label: "lx_tier_res", color: C.wine } };
  // クイズ解説からのジャンプを受けたら、その用語で絞り込む
  useEffect(() => {
    if (jump && jump.tab === "lexicon" && jump.lexTerm) {
      setCat(ALL);
      setQuery(jump.lexTerm);
    }
  }, [jump && jump.nonce]);
  const q = query.trim();
  const byCat = cat === ALL ? LEXICON : LEXICON.filter((g) => g.cat === cat);
  const byTier = tier === "all" ? byCat : byCat.filter((g) => (g.tier || "prod") === tier);
  const list = q === "" ? byTier : byTier.filter((g) => {
    const hayNorm = normalizeSearch([g.t, g.en, g.d, g.say, g.dEn, g.sayEn].filter(Boolean).join(" "));
    const { norm, extra } = expandQuery(q);
    // エイリアス一致（略語→別名）があればまずそれで判定
    if (extra.some((a) => a && hayNorm.includes(a))) return true;
    // 複数キーワードはAND（正規化はスペースを潰すので、元クエリの空白で分割してから各語を正規化）
    const parts = q.split(/[\s\u3000]+/).map(normalizeSearch).filter(Boolean);
    if (parts.length > 1) return parts.every((p) => hayNorm.includes(p));
    return hayNorm.includes(norm);
  });
  // 用語 → 関連クイズへ（道場のクイズを、その用語を含む問題に絞る）
  // 「MLA（潜在注意）」「MCP（詳説）」等の括弧・スラッシュ付き接尾辞を除いた主要語で検索精度を上げる
  const coreTerm = (g) => {
    const base = lang === "en" ? (g.en || g.t) : g.t;
    return base.split(/[（(／/]/)[0].trim() || base;
  };
  const toQuiz = (g) => setJump({ tab: "dojo", dojoView: "mcq", quizQuery: coreTerm(g) });
  return (
    <div>
      <SectionTitle jp={"アーキテクト用語辞典 — 一段深く語るための" + LEXICON.length + "語"} en="Architect Lexicon" />
      <div style={{ fontSize: 12, color: C.muted, marginBottom: 12 }}>
        {t(lang, "lx_intro")}
      </div>
      <input className="gh-input" value={query} onChange={(e) => setQuery(e.target.value)}
             placeholder={t(lang, "lx_search")}
             style={{ width: "100%", boxSizing: "border-box", marginBottom: 12, fontFamily: "inherit" }} />
      <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
        {cats.map((c) => (
          <button key={c} className="gh-btn" onClick={() => setCat(c)}
                  style={cat === c ? { borderColor: C.gold, color: C.gold } : {}}>{catLabel(c)}</button>
        ))}
        <span style={{ flex: 1 }} />
        <span style={{ fontSize: 11, color: C.dim }}>{list.length}{t(lang, "lx_count")}</span>
      </div>
      <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
        {TIERS.map(([tv, k]) => {
          const active = tier === tv;
          const col = tv === "prod" ? C.teal : tv === "emerg" ? C.gold : tv === "res" ? C.wine : C.muted;
          return (
            <button key={tv} className="gh-btn" onClick={() => setTier(tv)}
                    style={{ fontSize: 11.5, ...(active ? { borderColor: col, color: col } : {}) }}>{t(lang, k)}</button>
          );
        })}
      </div>
      {list.length === 0 ? (
        <div style={{ fontSize: 12, color: C.muted, padding: "20px 0", textAlign: "center" }}>{t(lang, "lx_nomatch")}</div>
      ) : (
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%, 290px),1fr))", gap: 12 }}>
        {list.map((g) => (
          <Card key={g.t}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
              <span className="gh-display" style={{ fontSize: 16, color: C.gold }}>{lang === "en" ? (g.en || g.t) : g.t}</span>
              <span style={{ fontSize: 10, color: C.teal, whiteSpace: "nowrap" }}>{catLabel(g.cat)}{lang === "en" ? (g.t ? " / " + g.t : "") : (g.en ? " / " + g.en : "")}</span>
            </div>
            {(() => {
              const tv = g.tier || "prod";
              const meta = tierMeta[tv] || tierMeta.prod;
              return (
                <span style={{ display: "inline-block", marginTop: 6, fontSize: 9.5, letterSpacing: ".05em", color: meta.color, border: `1px solid ${meta.color}`, borderRadius: 4, padding: "1px 6px" }}>
                  {t(lang, meta.label)}
                </span>
              );
            })()}
            <div style={{ fontSize: 12, color: C.text, margin: "8px 0", lineHeight: 1.7 }}>{lang === "en" ? (g.dEn || g.d) : g.d}</div>
            <div style={{ fontSize: 11.5, color: C.muted, fontStyle: "italic", borderTop: `1px solid ${C.line}`, paddingTop: 8 }}>{lang === "en" ? (g.sayEn || g.say) : g.say}</div>
            <div style={{ marginTop: 8 }}>
              <button onClick={() => toQuiz(g)}
                      style={{ background: "transparent", border: `1px solid ${C.line}`, borderRadius: 6, color: C.teal, fontSize: 11, padding: "4px 10px", cursor: "pointer", fontFamily: "inherit" }}>
                {t(lang, "lx_toquiz")}
              </button>
            </div>
          </Card>
        ))}
      </div>
      )}
    </div>
  );
}

