// Utilities
// =====================================================================
function seededPerm(seed, n) {
  const a = [...Array(n).keys()];
  let s = seed * 2654435761 % 4294967296;
  for (let i = n - 1; i > 0; i--) {
    s = (s * 1103515245 + 12345) % 2147483648;
    const j = s % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
