const EXAM_SETS = { 1: EXAM_SET1, 2: EXAM_SET2, 3: EXAM_SET3, 4: EXAM_SET4, 5: EXAM_SET5 };
const EXAM_SET_NOS = [1, 2, 3, 4, 5];

function buildDomainSet(domId) {
  const fromExams = [...EXAM_SET1, ...EXAM_SET2].filter(q => q.d === domId);
  const fromBank = BANK.filter(q => q.d === domId).map(q => ({ ...q }));
  const seen = new Set();
  const all = [];
  for (const q of [...fromExams, ...fromBank]) {
    if (seen.has(q.q)) continue;
    seen.add(q.q);
    all.push(q);
  }
  return shuffle(all).slice(0, 40);
}

