async function loadState() {
  try { const r = await window.storage.get(STORE_KEY); return r ? JSON.parse(r.value) : null; } catch { return null; }
}
async function saveState(s) { try { await window.storage.set(STORE_KEY, JSON.stringify(s)); } catch {} }
function todayStr() { return new Date().toISOString().slice(0, 10); }
function domName(id, lang) { return lang === "en" ? DOM_NAME_EN[id] : DOM_NAME[id]; }
// 問題テキストを言語に応じて取り出す（英語フィールドが無ければ日本語にフォールバック）
function qText(Q, lang) { return lang === "en" && Q.qEn ? Q.qEn : Q.q; }
function qOpts(Q, lang) { return lang === "en" && Q.oEn ? Q.oEn : Q.o; }
function qExpl(Q, lang) { return lang === "en" && Q.eEn ? Q.eEn : Q.e; }
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}
function arrEq(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) return false;
  if (a.length !== b.length) return false;
  const sa = [...a].sort(), sb = [...b].sort();
  return sa.every((v, i) => v === sb[i]);
}

function App() {
  const [tab, setTab] = useState("home");
  const [state, setState] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const [lang, setLang] = useState("ja");
  const t = T[lang];

  useEffect(() => {
    loadState().then(s => {
      const init = s || { progress: {}, meta: { streak: 0, lastDay: "", dailyDay: "", dailyCount: 0 }, review: [] };
      if (!init.review) init.review = [];
      setState(init);
      setLoaded(true);
    });
  }, []);

  const persist = (next) => { setState(next); saveState(next); };

  // 弱点問題（間違えた問題）を蓄積／解消する
  const addReview = (q) => {
    setState(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      if (!next.review) next.review = [];
      const key = q.q;
      if (!next.review.some(r => r.q === key)) {
        next.review.push({ d: q.d, q: q.q, o: q.o, a: q.a, e: q.e, multi: !!q.multi });
      }
      saveState(next);
      return next;
    });
  };
  const removeReview = (qText) => {
    setState(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      next.review = (next.review || []).filter(r => r.q !== qText);
      saveState(next);
      return next;
    });
  };
  const clearReview = () => {
    setState(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      next.review = [];
      saveState(next);
      return next;
    });
  };

  const record = (domId, correct) => {
    setState(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      if (!next.progress[domId]) next.progress[domId] = { correct: 0, attempts: 0 };
      next.progress[domId].attempts++;
      if (correct) next.progress[domId].correct++;
      const today = todayStr();
      if (next.meta.dailyDay !== today) { next.meta.dailyDay = today; next.meta.dailyCount = 0; }
      next.meta.dailyCount++;
      if (next.meta.lastDay !== today) {
        const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
        next.meta.streak = next.meta.lastDay === yesterday ? next.meta.streak + 1 : 1;
        next.meta.lastDay = today;
      }
      saveState(next);
      return next;
    });
  };

  if (!loaded) return <div style={{ padding: 40, textAlign: "center", color: C.deep }}>{t.loading}</div>;

  const reviewCount = (state.review || []).length;
  const TABS = [
    ["home", t.tabHome], ["quiz", t.tabQuiz], ["exam", t.tabExam],
    ["review", reviewCount > 0 ? `${t.tabReview} (${reviewCount})` : t.tabReview],
    ["diagram", t.tabDiagram], ["compare", t.tabCompare], ["confuse", t.tabConfuse], ["glossary", t.tabGlossary],
  ];

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: C.ink, background: "#FFFDF9", minHeight: "100vh" }}>
      <div style={{ background: C.deep, color: "#fff", padding: "16px 18px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <div style={{ fontSize: 19, fontWeight: 700 }}>
            <span style={{ color: C.primary }}>aws</span> {t.appTitle}
          </div>
          <div style={{ fontSize: 12, opacity: 0.85, marginTop: 2 }}>{t.appSub}</div>
        </div>
        <div style={{ display: "flex", background: "rgba(255,255,255,.15)", borderRadius: 20, padding: 3 }}>
          {["ja", "en"].map(l => (
            <button key={l} onClick={() => setLang(l)}
              style={{ border: "none", cursor: "pointer", borderRadius: 16, padding: "5px 12px", fontSize: 12, fontWeight: 700,
                background: lang === l ? C.primary : "transparent", color: lang === l ? C.deep : "#fff" }}>
              {l === "ja" ? "日本語" : "English"}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", borderBottom: `2px solid ${C.mid}`, background: C.light }}>
        {TABS.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)}
            style={{ flex: "1 1 auto", padding: "11px 8px", border: "none", cursor: "pointer",
              background: tab === k ? "#fff" : "transparent", color: tab === k ? C.deep : C.ink,
              fontWeight: tab === k ? 700 : 500, fontSize: 13, borderBottom: tab === k ? `3px solid ${C.primary}` : "3px solid transparent" }}>
            {label}
          </button>
        ))}
      </div>
      <div style={{ padding: 16, maxWidth: 820, margin: "0 auto" }}>
        {tab === "home" && <Home state={state} lang={lang} t={t} />}
        {tab === "quiz" && <Quiz onAnswer={record} lang={lang} t={t} />}
        {tab === "exam" && <Exam onAnswer={record} onWrong={addReview} lang={lang} t={t} />}
        {tab === "review" && <Review state={state} onAnswer={record} onResolve={removeReview} onClear={clearReview} lang={lang} t={t} />}
        {tab === "diagram" && <Diagrams lang={lang} t={t} />}
        {tab === "compare" && <Compare lang={lang} t={t} />}
        {tab === "confuse" && <Confuse lang={lang} t={t} />}
        {tab === "glossary" && <Glossary lang={lang} t={t} />}
      </div>
    </div>
  );
}

function Home({ state, lang, t }) {
  const totals = useMemo(() => {
    let c = 0, a = 0;
    Object.values(state.progress).forEach(p => { c += p.correct; a += p.attempts; });
    return { c, a, rate: a ? Math.round((c / a) * 100) : 0 };
  }, [state]);
  const weak = useMemo(() => DOMAINS.map(d => {
    const p = state.progress[d.id] || { correct: 0, attempts: 0 };
    const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : null;
    return { ...d, rate, attempts: p.attempts };
  }).filter(d => d.attempts > 0).sort((a, b) => a.rate - b.rate), [state]);
  const dailyPct = Math.min(100, Math.round((state.meta.dailyCount / DAILY_GOAL) * 100));
  return (
    <div>
      <div style={{ marginBottom: 16 }}>
        <Stat label={t.overallRate} value={`${totals.rate}%`} sub={`${totals.c}/${totals.a}${t.questionsUnit}`} color={totals.rate >= PASS ? C.ok : C.primary} />
      </div>
      <Card title={`${t.dailyGoal} (${state.meta.dailyCount}/${DAILY_GOAL})`}>
        <Bar pct={dailyPct} color={dailyPct >= 100 ? C.ok : C.primary} />
        <div style={{ fontSize: 12, marginTop: 6, color: "#6b5d52" }}>{dailyPct >= 100 ? t.dailyDone : t.dailyRemain(DAILY_GOAL - state.meta.dailyCount)}</div>
      </Card>
      <Card title={t.domMastery}>
        {DOMAINS.map(d => {
          const p = state.progress[d.id] || { correct: 0, attempts: 0 };
          const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : 0;
          return (
            <div key={d.id} style={{ marginBottom: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span style={{ fontWeight: 600 }}>
                  <span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
                  {domName(d.id, lang)}
                </span>
                <span style={{ color: "#6b5d52" }}>{d.pct}% · {p.attempts ? `${rate}%` : t.notStarted}</span>
              </div>
              <Bar pct={rate} color={d.hue} faint={!p.attempts} />
            </div>
          );
        })}
      </Card>
      {weak.length > 0 && (
        <Card title={t.weakDomains}>
          {weak.slice(0, 3).map(d => (
            <div key={d.id} style={{ fontSize: 13, padding: "6px 0", borderBottom: `1px solid ${C.light}` }}>
              <span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
              {domName(d.id, lang)} — <strong style={{ color: d.rate < PASS ? C.ng : C.ok }}>{d.rate}%</strong>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}

function Stat({ label, value, sub, color }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14 }}>
      <div style={{ fontSize: 11.5, color: "#6b5d52" }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 800, color }}>{value}</div>
      <div style={{ fontSize: 11, color: "#9b8d82" }}>{sub}</div>
    </div>
  );
}
function Card({ title, children }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep, marginBottom: 10 }}>{title}</div>
      {children}
    </div>
  );
}
function Bar({ pct, color, faint }) {
  return (
    <div style={{ background: C.light, borderRadius: 8, height: 9, overflow: "hidden" }}>
      <div style={{ width: `${pct}%`, height: "100%", background: faint ? C.mid : color, transition: "width .3s" }} />
    </div>
  );
}

function Quiz({ onAnswer, lang, t }) {
  const en = lang === "en";
  const [filter, setFilter] = useState("ALL");
  const [shuf, setShuf] = useState(false);
  const [pos, setPos] = useState(0);
  const [sel, setSel] = useState(null);
  const [seed, setSeed] = useState(0);
  const pool = useMemo(() => {
    const idxs = filter === "ALL" ? BANK.map((_, i) => i) : BANK.map((_, i) => i).filter(i => BANK[i].d === filter);
    return shuf ? shuffle(idxs) : idxs;
  }, [filter, shuf, seed]);
  useEffect(() => { setPos(0); setSel(null); }, [pool]);
  if (pool.length === 0) return null;
  const qi = pool[Math.min(pos, pool.length - 1)];
  const Q = BANK[qi];
  const choose = (i) => { if (sel !== null) return; setSel(i); onAnswer(Q.d, i === Q.a); };
  const go = (d) => { setSel(null); setPos(p => Math.max(0, Math.min(pool.length - 1, p + d))); };
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
        <div style={{ fontSize: 13, color: "#9b8d82", fontWeight: 600 }}>{en ? `${pool.length} questions` : `全${pool.length}問`}</div>
        <div style={{ display: "inline-flex", background: C.light, borderRadius: 20, padding: 3 }}>
          {[[false, en ? "Fixed order" : "固定順"], [true, en ? "Random" : "ランダム"]].map(([val, label]) => (
            <button key={String(val)} onClick={() => { setShuf(val); setSeed(x => x + 1); }}
              style={{ border: "none", cursor: "pointer", borderRadius: 16, padding: "6px 16px", fontSize: 12.5, fontWeight: 700,
                background: shuf === val ? "#fff" : "transparent", color: shuf === val ? C.deep : "#9b8d82",
                boxShadow: shuf === val ? "0 1px 3px rgba(0,0,0,.12)" : "none" }}>
              {label}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
        {["ALL", ...DOMAINS.map(d => d.id)].map(k => (
          <button key={k} onClick={() => setFilter(k)}
            style={{ padding: "6px 14px", borderRadius: 18, fontSize: 13, cursor: "pointer",
              border: `1.5px solid ${filter === k ? C.primary : C.mid}`, background: filter === k ? C.primary : "#fff", color: filter === k ? C.deep : C.ink, fontWeight: 700 }}>
            {k === "ALL" ? t.allFields : k}
          </button>
        ))}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={() => go(-1)} disabled={pos === 0}
          style={{ padding: "9px 16px", borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: pos === 0 ? "#bcae9f" : C.ink, fontWeight: 700, fontSize: 13, cursor: pos === 0 ? "default" : "pointer" }}>
          ← {en ? "Prev" : "前の問題"}
        </button>
        <span style={{ fontSize: 13.5, color: "#9b8d82", fontWeight: 600 }}>{pos + 1} / {pool.length}</span>
      </div>
      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 18 }}>
        <div style={{ fontSize: 11.5, color: "#fff", background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 5, padding: "3px 10px", marginBottom: 14 }}>{Q.d} · {domName(Q.d, lang)}</div>
        <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 16, lineHeight: 1.5 }}>{qText(Q, lang)}</div>
        {qOpts(Q, lang).map((opt, i) => {
          let bg = "#fff", bd = C.mid, col = C.ink;
          if (sel !== null) {
            if (i === Q.a) { bg = "#E8F5EE"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; }
          }
          return (
            <button key={i} onClick={() => choose(i)} disabled={sel !== null}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 10, padding: "14px 16px", borderRadius: 10,
                border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel === null ? "pointer" : "default",
                fontSize: 14, lineHeight: 1.4, fontWeight: sel !== null && i === Q.a ? 700 : 500 }}>
              <span style={{ fontWeight: 700, marginRight: 10 }}>{"ABCD"[i]}</span>{opt}
            </button>
          );
        })}
        {sel !== null && (
          <div style={{ marginTop: 12 }}>
            <div style={{ background: C.light, borderRadius: 9, padding: 13, fontSize: 13.5, lineHeight: 1.55 }}>
              <strong style={{ color: sel === Q.a ? C.ok : C.ng }}>{sel === Q.a ? t.correct : t.incorrect}</strong>・{t.answerIs("ABCD"[Q.a])}{qExpl(Q, lang)}
            </div>
            {pos + 1 < pool.length && (
              <button onClick={() => go(1)} style={{ marginTop: 12, width: "100%", padding: 13, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{t.nextQ}</button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function Compare({ lang, t }) {
  const en = lang === "en";
  const [q, setQ] = useState("");
  const list = COMPARE_TABLES.filter(tb => {
    if (!q) return true;
    const blob = [tb.title, tb.titleEn, ...(tb.headers || []), ...(tb.headersEn || []), ...(tb.rows || []).flat(), ...(tb.rowsEn || []).flat()].join(" ").toLowerCase();
    return blob.includes(q.toLowerCase());
  });
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder={t.compareSearch}
        style={{ width: "100%", padding: 11, borderRadius: 9, border: `1.5px solid ${C.mid}`, fontSize: 14, marginBottom: 12, boxSizing: "border-box" }} />
      <div style={{ fontSize: 12, color: "#9b8d82", marginBottom: 12 }}>{t.compareIntro}</div>
      {list.map((tb, ti) => {
        const headers = en && tb.headersEn ? tb.headersEn : tb.headers;
        const rows = en && tb.rowsEn ? tb.rowsEn : tb.rows;
        return (
          <div key={ti} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: C.deep, marginBottom: 12 }}>{en && tb.titleEn ? tb.titleEn : tb.title}</div>
            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
                <thead>
                  <tr style={{ background: C.light }}>
                    {headers.map((h, i) => (
                      <th key={i} style={{ textAlign: "left", padding: "9px 10px", color: C.accent, fontWeight: 700, fontSize: 12.5, borderBottom: `2px solid ${C.mid}`, whiteSpace: "nowrap" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r, ri) => (
                    <tr key={ri} style={{ borderBottom: `1px solid ${C.light}` }}>
                      {r.map((cell, ci) => (
                        <td key={ci} style={{ padding: "9px 10px", lineHeight: 1.4, color: ci === 0 ? C.deep : C.ink, fontWeight: ci === 0 ? 700 : 500, verticalAlign: "top" }}>{cell}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );
      })}
      {list.length === 0 && <div style={{ textAlign: "center", color: "#9b8d82", padding: 20 }}>{t.noMatch}</div>}
    </div>
  );
}

function Confuse({ lang, t }) {
  const [q, setQ] = useState("");
  const list = CONFUSE.filter(c => !q || c.join("").toLowerCase().includes(q.toLowerCase()));
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder={t.confuseSearch}
        style={{ width: "100%", padding: 11, borderRadius: 9, border: `1.5px solid ${C.mid}`, fontSize: 14, marginBottom: 14, boxSizing: "border-box" }} />
      {list.map((c, i) => (
        <div key={i} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 10, padding: 13, marginBottom: 10 }}>
          <div style={{ fontWeight: 700, color: C.deep, fontSize: 13.5, marginBottom: 5 }}>{lang === "en" && c[3] ? c[3] : c[0]}</div>
          <div style={{ fontSize: 13, lineHeight: 1.5, marginBottom: 4 }}>{lang === "en" && c[4] ? c[4] : c[1]}</div>
          <div style={{ fontSize: 12, color: C.primary, fontWeight: 600 }}>{t.judgeAxis}：{lang === "en" && c[5] ? c[5] : c[2]}</div>
        </div>
      ))}
      {list.length === 0 && <div style={{ textAlign: "center", color: "#9b8d82", padding: 20 }}>{t.noMatch}</div>}
    </div>
  );
}

function Glossary({ lang, t }) {
  const [q, setQ] = useState("");
  const [cat, setCat] = useState("すべて");
  const list = GLOSSARY.filter(g => {
    if (cat !== "すべて" && g[0] !== cat) return false;
    if (!q) return true;
    return (g[1] + g[2] + g[3] + (g[4] || "")).toLowerCase().includes(q.toLowerCase());
  });
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder={t.glossarySearch}
        style={{ width: "100%", padding: 11, borderRadius: 9, border: `1.5px solid ${C.mid}`, fontSize: 14, marginBottom: 10, boxSizing: "border-box" }} />
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 14 }}>
        {GLOSSARY_CATS.map(k => (
          <button key={k} onClick={() => { setCat(k); setOpen(""); }}
            style={{ padding: "5px 11px", borderRadius: 16, fontSize: 12, cursor: "pointer", border: `1px solid ${cat === k ? C.primary : C.mid}`, background: cat === k ? C.primary : "#fff", color: cat === k ? C.deep : C.ink, fontWeight: 600 }}>
            {k === "すべて" ? t.allFields : k}
          </button>
        ))}
      </div>
      {list.map((g, i) => (
        <div key={i} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 10, padding: 13, marginBottom: 9 }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 4, flexWrap: "wrap" }}>
            <span style={{ background: DOM_HUE[g[0]], color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 10.5 }}>{g[0]}</span>
            <span style={{ fontWeight: 700, fontSize: 14, color: C.deep }}>{g[1]}</span>
            {g[2] !== "-" && <span style={{ fontSize: 11.5, color: "#9b8d82" }}>{g[2]}</span>}
          </div>
          <div style={{ fontSize: 13, lineHeight: 1.5 }}>{lang === "en" && g[4] ? g[4] : g[3]}</div>
        </div>
      ))}
      {list.length === 0 && <div style={{ textAlign: "center", color: "#9b8d82", padding: 20 }}>{t.noMatch}</div>}
    </div>
  );
}

function Review({ state, onAnswer, onResolve, onClear, lang, t }) {
  const en = lang === "en";
  const list = state.review || [];
  const [phase, setPhase] = useState("list"); // list | quiz
  const [pos, setPos] = useState(0);
  const [pick, setPick] = useState([]);
  const [revealed, setRevealed] = useState(false);

  if (list.length === 0) {
    return (
      <Card title={t.reviewTitle}>
        <div style={{ fontSize: 13, color: "#6b5d52", lineHeight: 1.6 }}>{t.reviewEmpty}</div>
      </Card>
    );
  }

  if (phase === "list") {
    return (
      <div>
        <Card title={t.reviewTitle}>
          <div style={{ fontSize: 13, color: "#5a4d43", lineHeight: 1.6, marginBottom: 12 }}>{t.reviewIntro(list.length)}</div>
          <button onClick={() => { setPhase("quiz"); setPos(0); setPick([]); setRevealed(false); }}
            style={{ width: "100%", padding: 13, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer", marginBottom: 8 }}>
            {t.reviewStart}
          </button>
          <button onClick={onClear} style={{ width: "100%", padding: 10, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ng, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{t.reviewClear}</button>
        </Card>
        {list.map((q, i) => (
          <div key={i} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 10, padding: 12, marginBottom: 9 }}>
            <div style={{ fontSize: 13, fontWeight: 600, lineHeight: 1.5 }}>
              <span style={{ background: DOM_HUE[q.d], color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 10.5, marginRight: 6 }}>{q.d}</span>{q.q}
            </div>
          </div>
        ))}
      </div>
    );
  }

  // quiz
  const safePos = Math.min(pos, list.length - 1);
  const Q = list[safePos];
  if (!Q) {
    return (
      <Card title={t.reviewTitle}>
        <div style={{ fontSize: 14, color: C.ok, fontWeight: 700, textAlign: "center", padding: 10 }}>{t.reviewAllDone}</div>
        <button onClick={() => setPhase("list")} style={{ width: "100%", marginTop: 10, padding: 12, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.reviewBackList}</button>
      </Card>
    );
  }
  const multi = !!Q.multi;
  const numNeeded = Array.isArray(Q.a) ? Q.a.length : 1;
  const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
  const isCorrect = arrEq(pick, correctAns);

  const toggle = (i) => {
    if (revealed) return;
    if (multi) setPick(p => p.includes(i) ? p.filter(x => x !== i) : [...p, i]);
    else setPick([i]);
  };
  const check = () => {
    setRevealed(true);
    onAnswer(Q.d, isCorrect);
    if (isCorrect) onResolve(Q.q);
  };
  const next = () => {
    // 正解で消えた場合は同じ index に次の問題が来る。不正解なら次へ。
    const nextPos = isCorrect ? safePos : safePos + 1;
    setPos(nextPos);
    setPick([]);
    setRevealed(false);
  };
  const remaining = list.length;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, background: C.deep, color: "#fff", borderRadius: 9, padding: "9px 14px" }}>
        <span style={{ fontSize: 13, fontWeight: 700 }}>{t.reviewTitle}</span>
        <span style={{ fontSize: 13, fontWeight: 700 }}>{en ? "Remaining" : "残り"}: {remaining}</span>
      </div>
      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11, color: "#fff", background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>{Q.d} · {domName(Q.d, lang)}</div>
        {multi && <div style={{ display: "inline-block", marginLeft: 8, fontSize: 11, color: C.accent, fontWeight: 700, border: `1px solid ${C.accent}`, borderRadius: 4, padding: "2px 8px" }}>{t.multiSelect(numNeeded)}</div>}
        <div style={{ fontSize: 15, fontWeight: 600, margin: "12px 0 14px", lineHeight: 1.6 }}>{qText(Q, lang)}</div>
        {qOpts(Q, lang).map((opt, i) => {
          const on = pick.includes(i);
          let bg = on ? C.light : "#fff", bd = on ? C.primary : C.mid, col = C.ink, fw = on ? 700 : 500;
          let mark = on ? "✓" : "ABCD"[i], markBg = on ? C.primary : "#fff", markBd = on ? C.primary : C.mid;
          if (revealed) {
            if (correctAns.includes(i)) { bg = "#E8F5EE"; bd = C.ok; col = C.ok; fw = 700; markBg = C.ok; markBd = C.ok; mark = "✓"; }
            else if (on) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; fw = 700; markBg = C.ng; markBd = C.ng; mark = "✕"; }
            else { mark = "ABCD"[i]; markBg = "#fff"; markBd = C.mid; }
          }
          return (
            <button key={i} onClick={() => toggle(i)} disabled={revealed}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9,
                border: `1.5px solid ${bd}`, background: bg, color: col, cursor: revealed ? "default" : "pointer", fontSize: 13.5, lineHeight: 1.45, fontWeight: fw }}>
              <span style={{ display: "inline-block", minWidth: 20, height: 20, lineHeight: "18px", textAlign: "center", marginRight: 8, borderRadius: multi ? 4 : 10, border: `2px solid ${markBd}`, background: markBg, color: markBg === "#fff" ? C.deep : "#fff", fontSize: 11, fontWeight: 700 }}>{mark}</span>{opt}
            </button>
          );
        })}
        {revealed && (
          <div style={{ marginTop: 12, background: C.light, borderRadius: 9, padding: 13, fontSize: 13.5, lineHeight: 1.55 }}>
            <strong style={{ color: isCorrect ? C.ok : C.ng }}>{isCorrect ? t.correct : t.incorrect}</strong>・{t.answerIs(correctAns.map(x => "ABCD"[x]).join(", "))}{qExpl(Q, lang)}
            {isCorrect && <div style={{ color: C.ok, fontWeight: 700, marginTop: 6 }}>✓ {t.reviewMastered}</div>}
          </div>
        )}
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
        <button onClick={() => setPhase("list")} style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ink, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.reviewBackList}</button>
        {!revealed ? (
          <button onClick={check} disabled={pick.length === 0} style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: pick.length === 0 ? C.mid : C.accent, color: "#fff", fontWeight: 700, fontSize: 14, cursor: pick.length === 0 ? "default" : "pointer" }}>{t.showAnswer}</button>
        ) : (
          <button onClick={next} style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.checkContinue}</button>
        )}
      </div>
    </div>
  );
}

function Exam({ onAnswer, onWrong, lang, t }) {
  const en = lang === "en";
  const [mode, setMode] = useState("normal");
  const [examMode, setExamMode] = useState("practice");
  const [setNo, setSetNo] = useState(null);
  const [domKey, setDomKey] = useState(null);
  const [phase, setPhase] = useState("select");
  const [pos, setPos] = useState(0);
  const [picks, setPicks] = useState({});
  const [flags, setFlags] = useState({});
  const [timeLeft, setTimeLeft] = useState(130 * 60);
  const [qs, setQs] = useState([]);
  const [title, setTitle] = useState("");
  const [revealed, setRevealed] = useState({});

  const isPractice = examMode === "practice";

  const score = () => {
    qs.forEach((Q, i) => {
      const pick = picks[i] || [];
      const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
      const ok = arrEq(pick, correctAns);
      onAnswer(Q.d, ok);
      if (!ok && onWrong) onWrong(Q);
    });
    setPhase("result");
  };

  useEffect(() => {
    if (phase !== "run" || isPractice) return;
    if (timeLeft <= 0) { score(); return; }
    const id = setInterval(() => setTimeLeft(tl => tl - 1), 1000);
    return () => clearInterval(id);
  }, [phase, timeLeft, isPractice]);

  const begin = (questions, label) => {
    setQs(questions); setTitle(label); setPos(0); setPicks({}); setFlags({}); setRevealed({}); setTimeLeft(130 * 60); setPhase("run");
  };
  const startNormal = (n) => { setSetNo(n); begin(EXAM_SETS[n], `${t.setLabel} ${n}`); };
  const startDomain = (id) => { setDomKey(id); begin(buildDomainSet(id), domName(id, lang)); };
  const restart = () => { if (mode === "normal") startNormal(setNo); else startDomain(domKey); };

  const togglePick = (qi, optIdx, multi) => {
    if (isPractice && revealed[qi]) return;
    setPicks(p => {
      const cur = p[qi] || [];
      if (multi) { const has = cur.includes(optIdx); return { ...p, [qi]: has ? cur.filter(x => x !== optIdx) : [...cur, optIdx] }; }
      return { ...p, [qi]: [optIdx] };
    });
  };

  const revealPractice = (qi) => {
    const Q = qs[qi];
    const pick = picks[qi] || [];
    const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
    const ok = arrEq(pick, correctAns);
    onAnswer(Q.d, ok);
    if (!ok && onWrong) onWrong(Q);
    setRevealed(r => ({ ...r, [qi]: true }));
  };

  const fmtTime = (s) => `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

  if (phase === "select") {
    const modeBtns = [
      ["normal", en ? "Standard sets" : "通常セット"],
      ["domain", en ? "Domain focus" : "ドメイン重点版"],
    ];
    const examModeBtns = [
      ["practice", t.examModePractice],
      ["real", t.examModeReal],
    ];
    return (
      <div>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 8 }}>
          <div style={{ display: "inline-flex", background: C.light, borderRadius: 22, padding: 4 }}>
            {examModeBtns.map(([k, label]) => (
              <button key={k} onClick={() => setExamMode(k)}
                style={{ border: "none", cursor: "pointer", borderRadius: 18, padding: "9px 22px", fontSize: 13, fontWeight: 700,
                  background: examMode === k ? "#fff" : "transparent", color: examMode === k ? C.deep : "#9b8d82",
                  boxShadow: examMode === k ? "0 1px 4px rgba(0,0,0,.12)" : "none" }}>
                {label}
              </button>
            ))}
          </div>
        </div>
        <div style={{ textAlign: "center", fontSize: 12, color: "#9b8d82", marginBottom: 16, lineHeight: 1.5, padding: "0 10px" }}>
          {isPractice ? t.examModePracticeDesc : t.examModeRealDesc}
        </div>

        <div style={{ display: "flex", gap: 6, marginBottom: 14, flexWrap: "wrap" }}>
          {modeBtns.map(([k, label]) => (
            <button key={k} onClick={() => setMode(k)}
              style={{ flex: "1 1 45%", padding: "10px 8px", borderRadius: 10, cursor: "pointer", fontSize: 12.5, fontWeight: 700,
                border: `1.5px solid ${mode === k ? C.primary : C.mid}`, background: mode === k ? C.primary : "#fff", color: mode === k ? C.deep : C.ink }}>
              {label}
            </button>
          ))}
        </div>
        {mode === "normal" && (
          <>
            <Card title={t.examTitle}><div style={{ fontSize: 13, lineHeight: 1.6, color: "#5a4d43" }}>{t.examDesc}</div></Card>
            {EXAM_SET_NOS.map(n => (
              <button key={n} onClick={() => startNormal(n)}
                style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
                  border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontWeight: 700, fontSize: 15, color: C.deep }}>{t.setLabel} {n}</span>
                <span style={{ fontSize: 12.5, fontWeight: 700, color: C.primary }}>{t.start}</span>
              </button>
            ))}
          </>
        )}
        {mode === "domain" && DOMAINS.map(d => (
          <button key={d.id} onClick={() => startDomain(d.id)}
            style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span>
              <span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "2px 7px", fontSize: 11, marginRight: 8, fontWeight: 700 }}>{d.id}</span>
              <span style={{ fontWeight: 700, fontSize: 14, color: C.deep }}>{domName(d.id, lang)}</span>
            </span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: C.primary }}>{t.start}</span>
          </button>
        ))}
      </div>
    );
  }

  if (phase === "result") {
    let c = 0;
    const wrong = [];
    qs.forEach((Q, i) => {
      const pick = picks[i] || [];
      const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
      if (arrEq(pick, correctAns)) c++; else wrong.push({ Q, pick, correctAns });
    });
    const rate = Math.round((c / qs.length) * 100);
    const passed = rate >= PASS;
    return (
      <div>
        <div style={{ background: passed ? "#E8F5EE" : "#FBEAE8", border: `2px solid ${passed ? C.ok : C.ng}`, borderRadius: 12, padding: 18, textAlign: "center", marginBottom: 14 }}>
          <div style={{ fontSize: 13, color: "#6b5d52" }}>{title} {t.result}</div>
          <div style={{ fontSize: 40, fontWeight: 800, color: passed ? C.ok : C.ng }}>{rate}%</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: passed ? C.ok : C.ng }}>{passed ? t.reachedPass : t.needMore(PASS - rate)}</div>
          <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 4 }}>{t.correctOf(c, qs.length)}</div>
        </div>
        <Card title={t.wrongTitle(wrong.length)}>
          {wrong.length === 0 ? (
            <div style={{ fontSize: 13, color: C.ok }}>{t.allCorrect}</div>
          ) : wrong.map((w, idx) => (
            <div key={idx} style={{ padding: "8px 0", borderBottom: `1px solid ${C.light}`, fontSize: 13 }}>
              <div style={{ fontWeight: 600, marginBottom: 4 }}>
                <span style={{ background: DOM_HUE[w.Q.d], color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 10.5, marginRight: 6 }}>{w.Q.d}</span>{qText(w.Q, lang)}
              </div>
              <div style={{ color: C.ng, fontSize: 12.5 }}>{t.yourAnswer}：{w.pick.length ? w.pick.map(x => "ABCD"[x]).join(", ") : "—"}</div>
              <div style={{ color: C.ok, fontSize: 12.5 }}>{t.answer}：{w.correctAns.map(x => "ABCD"[x]).join(", ")} {w.correctAns.map(x => qOpts(w.Q, lang)[x]).join(" / ")}</div>
              <div style={{ color: "#6b5d52", fontSize: 12.5, marginTop: 2 }}>{qExpl(w.Q, lang)}</div>
            </div>
          ))}
        </Card>
        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={restart} style={{ flex: 1, padding: 13, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.retrySet}</button>
          <button onClick={() => setPhase("select")} style={{ flex: 1, padding: 13, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.toSetSelect}</button>
        </div>
      </div>
    );
  }

  const Q = qs[pos];
  const multi = !!Q.multi;
  const numNeeded = Array.isArray(Q.a) ? Q.a.length : 1;
  const pick = picks[pos] || [];
  const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
  const isRevealed = isPractice && revealed[pos];
  const isLastQ = pos + 1 >= qs.length;
  const answeredCount = Object.keys(picks).filter(k => (picks[k] || []).length > 0).length;
  const timeWarn = !isPractice && timeLeft <= 180;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, background: timeWarn ? "#FBEAE8" : C.deep, color: timeWarn ? C.ng : "#fff", borderRadius: 9, padding: "9px 14px" }}>
        <span style={{ fontSize: 13, fontWeight: 600 }}>
          {title} · {t.questionNo(pos + 1, qs.length)}
          <span style={{ marginLeft: 8, fontSize: 11, opacity: 0.8 }}>{isPractice ? t.examModePractice : t.examModeReal}</span>
        </span>
        {isPractice
          ? <span style={{ fontSize: 13, fontWeight: 700, opacity: 0.85 }}>{en ? "Answered" : "回答済"} {answeredCount}/{qs.length}</span>
          : <span style={{ fontSize: 17, fontWeight: 800 }}>{fmtTime(timeLeft)}</span>}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, color: "#9b8d82", marginBottom: 6 }}>
        <span>{en ? "Answered" : "回答済"} {answeredCount}/{qs.length}</span>
        <button onClick={() => setFlags(f => ({ ...f, [pos]: !f[pos] }))}
          style={{ border: "none", background: "none", cursor: "pointer", fontSize: 12, fontWeight: 700, color: flags[pos] ? C.primary : "#9b8d82" }}>
          {flags[pos] ? (en ? "★ Flagged" : "★ フラグ") : (en ? "☆ Flag" : "☆ フラグ")}
        </button>
      </div>
      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11, color: "#fff", background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>{Q.d} · {domName(Q.d, lang)}</div>
        {multi && <div style={{ display: "inline-block", marginLeft: 8, fontSize: 11, color: C.accent, fontWeight: 700, border: `1px solid ${C.accent}`, borderRadius: 4, padding: "2px 8px" }}>{t.multiSelect(numNeeded)}</div>}
        <div style={{ fontSize: 15, fontWeight: 600, margin: "12px 0 14px", lineHeight: 1.6 }}>{qText(Q, lang)}</div>
        {qOpts(Q, lang).map((opt, i) => {
          const on = pick.includes(i);
          let bg = on ? C.light : "#fff", bd = on ? C.primary : C.mid, col = C.ink, fw = on ? 700 : 500;
          let mark = on ? "✓" : "ABCD"[i], markBg = on ? C.primary : "#fff", markBd = on ? C.primary : C.mid;
          if (isRevealed) {
            const isCorrectOpt = correctAns.includes(i);
            if (isCorrectOpt) { bg = "#E8F5EE"; bd = C.ok; col = C.ok; fw = 700; markBg = C.ok; markBd = C.ok; mark = "✓"; }
            else if (on) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; fw = 700; markBg = C.ng; markBd = C.ng; mark = "✕"; }
            else { mark = "ABCD"[i]; markBg = "#fff"; markBd = C.mid; }
          }
          return (
            <button key={i} onClick={() => togglePick(pos, i, multi)} disabled={isRevealed}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9,
                border: `1.5px solid ${bd}`, background: bg, color: col, cursor: isRevealed ? "default" : "pointer", fontSize: 13.5, lineHeight: 1.45, fontWeight: fw }}>
              <span style={{ display: "inline-block", minWidth: 20, height: 20, lineHeight: "18px", textAlign: "center", marginRight: 8, borderRadius: multi ? 4 : 10, border: `2px solid ${markBd}`, background: markBg, color: markBg === "#fff" ? C.deep : "#fff", fontSize: 11, fontWeight: 700 }}>
                {mark}
              </span>{opt}
            </button>
          );
        })}
        {isRevealed && (
          <div style={{ marginTop: 12, background: C.light, borderRadius: 9, padding: 13, fontSize: 13.5, lineHeight: 1.55 }}>
            <strong style={{ color: arrEq(pick, correctAns) ? C.ok : C.ng }}>{arrEq(pick, correctAns) ? t.correct : t.incorrect}</strong>・{t.answerIs(correctAns.map(x => "ABCD"[x]).join(", "))}{qExpl(Q, lang)}
          </div>
        )}
      </div>

      {isPractice ? (
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <button onClick={() => setPos(p => Math.max(0, p - 1))} disabled={pos === 0}
            style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: pos === 0 ? "#bcae9f" : C.ink, fontWeight: 700, fontSize: 14, cursor: pos === 0 ? "default" : "pointer" }}>
            ← {en ? "Prev" : "前へ"}
          </button>
          {!isRevealed ? (
            <button onClick={() => revealPractice(pos)} disabled={pick.length === 0}
              style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: pick.length === 0 ? C.mid : C.accent, color: "#fff", fontWeight: 700, fontSize: 14, cursor: pick.length === 0 ? "default" : "pointer" }}>
              {t.showAnswer}
            </button>
          ) : isLastQ ? (
            <button onClick={score} style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: C.ok, color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.scoreBtn} ✓</button>
          ) : (
            <button onClick={() => setPos(p => p + 1)} style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.checkContinue}</button>
          )}
        </div>
      ) : (
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <button onClick={() => setPos(p => Math.max(0, p - 1))} disabled={pos === 0}
            style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: pos === 0 ? "#bcae9f" : C.ink, fontWeight: 700, fontSize: 14, cursor: pos === 0 ? "default" : "pointer" }}>
            ← {en ? "Prev" : "前へ"}
          </button>
          {pos + 1 < qs.length ? (
            <button onClick={() => setPos(p => p + 1)} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{en ? "Next" : "次へ"} →</button>
          ) : (
            <button onClick={score} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.ok, color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.scoreBtn} ✓</button>
          )}
        </div>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(34px, 1fr))", gap: 5, marginTop: 14 }}>
        {qs.map((_, i) => {
          const ans = (picks[i] || []).length > 0;
          const fl = flags[i];
          const cur = i === pos;
          const done = isPractice && revealed[i];
          return (
            <button key={i} onClick={() => setPos(i)}
              style={{ aspectRatio: "1", borderRadius: 6, cursor: "pointer", fontSize: 11, fontWeight: 700,
                border: cur ? `2px solid ${C.deep}` : `1px solid ${C.mid}`, background: fl ? "#FFE6B3" : done ? C.ok : ans ? C.primary : "#fff", color: (ans || done) && !fl ? (done ? "#fff" : C.deep) : C.ink }}>
              {i + 1}
            </button>
          );
        })}
      </div>
      {!isPractice && (
        <button onClick={score} style={{ width: "100%", marginTop: 12, padding: 12, borderRadius: 9, border: `1.5px solid ${C.ok}`, background: "#fff", color: C.ok, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.scoreBtn} ✓</button>
      )}
    </div>
  );
}

function Diagrams({ lang, t }) {
  const en = lang === "en";
  const CATS = [
    ["interactive", en ? "Interactive" : "操作型"],
    ["tree", en ? "Decision trees" : "決定木"],
    ["hier", en ? "Hierarchy" : "階層関係"],
    ["layer", en ? "Layers" : "上下関係"],
    ["parallel", en ? "Parallel" : "並列関係"],
    ["flow", en ? "Flows" : "フロー"],
    ["concept", en ? "Concept maps" : "概念図"],
  ];
  const [cat, setCat] = useState("interactive");
  const [open, setOpen] = useState("");
  const Section = ({ id, title, children }) => (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, marginBottom: 12, overflow: "hidden" }}>
      <button onClick={() => setOpen(open === id ? "" : id)}
        style={{ width: "100%", textAlign: "left", padding: "13px 15px", border: "none", background: open === id ? C.light : "#fff", color: C.deep, fontWeight: 700, fontSize: 13.5, cursor: "pointer", display: "flex", justifyContent: "space-between" }}>
        <span>{title}</span><span>{open === id ? "−" : "+"}</span>
      </button>
      {open === id && <div style={{ padding: 15, borderTop: `1px solid ${C.light}` }}>{children}</div>}
    </div>
  );
  return (
    <div>
      <div style={{ fontSize: 12, color: "#9b8d82", marginBottom: 10 }}>{t.diagIntro}</div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 14 }}>
        {CATS.map(([k, label]) => (
          <button key={k} onClick={() => setCat(k)}
            style={{ padding: "6px 13px", borderRadius: 18, fontSize: 12.5, cursor: "pointer", fontWeight: 700,
              border: `1.5px solid ${cat === k ? C.primary : C.mid}`, background: cat === k ? C.primary : "#fff", color: cat === k ? C.deep : C.ink }}>
            {label}
          </button>
        ))}
      </div>

      {cat === "interactive" && <>
        <Section id="archbuilder" title={en ? "Build a 3-tier architecture (clickable)" : "3層アーキテクチャを組み立てる（クリック式）"}><ArchBuilder lang={lang} /></Section>
        <Section id="costsim" title={en ? "EC2 pricing simulator (slider)" : "EC2 料金シミュレーター（スライダー）"}><CostSimulator lang={lang} /></Section>
        <Section id="drsim" title={en ? "DR strategy simulator (RTO/RPO)" : "DR 戦略シミュレーター（RTO/RPO）"}><DrSimulator lang={lang} /></Section>
        <Section id="s3sim" title={en ? "S3 class chooser (sliders)" : "S3 クラス選定（スライダー）"}><S3Chooser lang={lang} /></Section>
        <Section id="scalesim" title={en ? "Auto Scaling simulator" : "Auto Scaling シミュレーター"}><ScaleSimulator lang={lang} /></Section>
        <Section id="iamsim" title={en ? "IAM policy evaluator (toggle)" : "IAM ポリシー評価器（トグル）"}><IamEvaluator lang={lang} /></Section>
      </>}

      {cat === "tree" && <>
        <Section id="storage" title={en ? "Storage decision tree" : "ストレージ選択の決定木"}><StorageTree lang={lang} /></Section>
        <Section id="db" title={en ? "Database decision tree" : "データベース選択の決定木"}><DBTree lang={lang} /></Section>
        <Section id="compute" title={en ? "Compute / purchase decision tree" : "コンピュート・購入の決定木"}><ComputeTree lang={lang} /></Section>
        <Section id="connect" title={en ? "On-prem connectivity decision tree" : "オンプレ接続の決定木"}><ConnectTree lang={lang} /></Section>
        <Section id="lb" title={en ? "Load balancer decision tree" : "ロードバランサー選択の決定木"}><LbTree lang={lang} /></Section>
      </>}

      {cat === "hier" && <>
        <Section id="org" title={en ? "Organizations hierarchy" : "Organizations の階層構造"}><OrgHierarchy lang={lang} /></Section>
        <Section id="iam" title={en ? "IAM permission scope hierarchy" : "IAM 権限スコープの階層"}><IamScopeHierarchy lang={lang} /></Section>
        <Section id="resp" title={en ? "Shared responsibility hierarchy" : "責任共有モデルの階層"}><RespHierarchy lang={lang} /></Section>
        <Section id="s3class" title={en ? "S3 storage class hierarchy" : "S3 ストレージクラスの階層"}><S3ClassHierarchy lang={lang} /></Section>
      </>}

      {cat === "layer" && <>
        <Section id="defense" title={en ? "Defense in depth (layers)" : "多層防御（上下のレイヤー）"}><DefenseLayers lang={lang} /></Section>
        <Section id="dr" title={en ? "DR strategies (RTO ladder)" : "DR 戦略（RTO の階段）"}><DrLadder lang={lang} /></Section>
        <Section id="caching" title={en ? "Caching layers (top to bottom)" : "キャッシュ階層（上から下へ）"}><CachingLayers lang={lang} /></Section>
        <Section id="osi" title={en ? "Network stack layers" : "ネットワークの層と AWS サービス"}><NetworkLayers lang={lang} /></Section>
      </>}

      {cat === "parallel" && <>
        <Section id="storageP" title={en ? "Storage types side by side" : "ストレージ種別の並列比較"}><StorageParallel lang={lang} /></Section>
        <Section id="msgP" title={en ? "SQS / SNS / EventBridge" : "SQS / SNS / EventBridge の並列比較"}><MsgParallel lang={lang} /></Section>
        <Section id="purchaseP" title={en ? "EC2 purchase options" : "EC2 購入オプションの並列比較"}><PurchaseParallel lang={lang} /></Section>
        <Section id="dbP" title={en ? "Database engines side by side" : "データベースの並列比較"}><DbParallel lang={lang} /></Section>
        <Section id="domains" title={en ? "Exam weight by domain" : "4ドメインの出題比率"}><DomainBars lang={lang} /></Section>
      </>}

      {cat === "flow" && <>
        <Section id="reqflow" title={en ? "Web request flow (3-tier)" : "Web リクエストの流れ（3 層）"}><RequestFlow lang={lang} /></Section>
        <Section id="queueflow" title={en ? "Decoupled queue flow" : "キューによる疎結合フロー"}><QueueFlow lang={lang} /></Section>
        <Section id="failflow" title={en ? "Multi-AZ failover flow" : "マルチ AZ フェイルオーバーの流れ"}><FailoverFlow lang={lang} /></Section>
        <Section id="fanout" title={en ? "SNS fan-out flow" : "SNS ファンアウトのフロー"}><FanoutFlow lang={lang} /></Section>
        <Section id="cicd" title={en ? "Blue/Green deploy flow" : "Blue/Green デプロイの流れ"}><BlueGreenFlow lang={lang} /></Section>
      </>}

      {cat === "concept" && <>
        <Section id="vpc" title={en ? "VPC concept map" : "VPC の概念図"}><VpcConcept lang={lang} /></Section>
        <Section id="waf" title={en ? "Edge protection concept" : "エッジ防御の概念図"}><EdgeConcept lang={lang} /></Section>
        <Section id="encmap" title={en ? "Encryption concept map" : "暗号化の概念図"}><EncryptionConcept lang={lang} /></Section>
        <Section id="globalmap" title={en ? "Global high-availability concept" : "グローバル高可用性の概念図"}><GlobalConcept lang={lang} /></Section>
      </>}
    </div>
  );
}

function DecisionWidget({ lang, steps, leaves, startKey = "start" }) {
  const en = lang === "en";
  const [path, setPath] = useState([]);
  const cur = path.length === 0 ? startKey : path[path.length - 1];
  const leaf = leaves[cur];
  return (
    <div>
      <div style={{ marginBottom: 10, fontSize: 12, color: "#9b8d82" }}>
        {path.length > 0 && <button onClick={() => setPath(p => p.slice(0, -1))} style={{ border: "none", background: "none", color: C.primary, cursor: "pointer", fontWeight: 700, padding: 0 }}>{en ? "← Back" : "← 戻る"}</button>}
      </div>
      {!leaf && steps[cur] && (
        <div>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.deep, marginBottom: 12 }}>{steps[cur].q}</div>
          {steps[cur].opts.map(([label, to]) => (
            <button key={to} onClick={() => setPath(p => [...p, to])}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "12px 14px", borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ink, cursor: "pointer", fontSize: 14, fontWeight: 600 }}>
              {label} →
            </button>
          ))}
        </div>
      )}
      {leaf && (
        <div style={{ background: "#E8F5EE", border: `2px solid ${C.ok}`, borderRadius: 10, padding: 14 }}>
          <div style={{ fontSize: 11, color: C.ok, fontWeight: 700 }}>{en ? "Conclusion" : "結論"}</div>
          <div style={{ fontSize: 16, fontWeight: 800, color: C.deep, margin: "4px 0" }}>{leaf[0]}</div>
          <div style={{ fontSize: 13, lineHeight: 1.5 }}>{leaf[1]}</div>
          <button onClick={() => setPath([])} style={{ marginTop: 12, padding: "8px 14px", borderRadius: 8, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{en ? "Restart" : "最初から"}</button>
        </div>
      )}
    </div>
  );
}

function StorageTree({ lang }) {
  const en = lang === "en";
  const steps = {
    start: { q: en ? "What kind of storage?" : "どの種類のストレージが必要か？", opts: [[en ? "Block (single instance disk)" : "ブロック（単一インスタンスのディスク）", "block"], [en ? "File (shared)" : "ファイル（共有）", "file"], [en ? "Object (large storage)" : "オブジェクト（大容量保管）", "object"]] },
    block: { q: en ? "Persistence?" : "永続性は必要か？", opts: [[en ? "Persistent" : "永続が必要", "ebs"], [en ? "Temporary, ultra-fast" : "一時・超高速", "instore"]] },
    file: { q: en ? "OS / use case?" : "OS・用途は？", opts: [[en ? "Linux/general (NFS)" : "Linux・汎用（NFS）", "efs"], [en ? "Windows (SMB)" : "Windows（SMB）", "fsxw"], [en ? "HPC/ML high throughput" : "HPC・ML 高スループット", "lustre"]] },
  };
  const leaves = {
    ebs: ["Amazon EBS", en ? "Persistent block storage tied to a single AZ" : "単一 AZ に固定される永続ブロックストレージ"],
    instore: [en ? "Instance Store" : "インスタンスストア", en ? "Ultra-fast but volatile; lost on stop" : "超高速だが揮発、停止で消える"],
    efs: ["Amazon EFS", en ? "Multi-AZ shared NFS, auto-scaling" : "複数 AZ 共有の自動拡張 NFS"],
    fsxw: ["FSx for Windows", en ? "SMB shared file with AD integration" : "AD 統合の SMB 共有ファイル"],
    lustre: ["FSx for Lustre", en ? "High-parallel HPC file system, S3-linked" : "S3 連携の高並列 HPC ファイルシステム"],
    object: ["Amazon S3", en ? "Highly durable object storage; pick a class by access pattern" : "高耐久のオブジェクトストレージ。アクセスパターンでクラスを選ぶ"],
  };
  return <DecisionWidget lang={lang} steps={steps} leaves={leaves} />;
}

function DBTree({ lang }) {
  const en = lang === "en";
  const steps = {
    start: { q: en ? "Data model?" : "データモデルは？", opts: [[en ? "Relational (SQL)" : "リレーショナル（SQL）", "rel"], [en ? "NoSQL" : "キーバリュー/ドキュメント（NoSQL）", "dynamo"], [en ? "In-memory cache" : "インメモリキャッシュ", "cache"], [en ? "Analytics / DWH" : "分析・DWH", "analytics"]] },
    rel: { q: en ? "Priority?" : "重視するのは？", opts: [[en ? "HA + auto-scale" : "高可用＋自動スケール", "aurora"], [en ? "Standard managed RDBMS" : "標準的なマネージド RDB", "rds"], [en ? "Intermittent load" : "断続的・変動負荷", "auroraless"]] },
    cache: { q: en ? "Persistence / advanced types?" : "永続化や高度なデータ型は必要？", opts: [[en ? "Yes" : "必要（永続・Pub/Sub）", "redis"], [en ? "No, simple fast" : "不要、単純高速キャッシュ", "memcached"]] },
    analytics: { q: en ? "Query pattern?" : "クエリパターンは？", opts: [[en ? "Continuous large analysis" : "継続的な大量分析（DWH）", "redshift"], [en ? "Ad-hoc on S3" : "アドホック・S3 にサーバーレス", "athena"]] },
  };
  const leaves = {
    rds: ["Amazon RDS", en ? "Managed RDB. Multi-AZ for availability, read replicas for read scaling" : "マネージド RDB。可用性はマルチ AZ、読み取り拡張はリードレプリカ"],
    aurora: ["Amazon Aurora", en ? "6-way replicated storage; up to 15 replicas; fast failover" : "6 多重ストレージ。最大 15 の低遅延レプリカと高速フェイルオーバー"],
    auroraless: ["Aurora Serverless", en ? "Auto-scales; pay per use. For intermittent workloads" : "負荷に応じ容量を自動増減し使った分だけ課金。断続負荷向け"],
    dynamo: ["Amazon DynamoDB", en ? "Single-digit ms NoSQL. DAX for μs reads, Global Tables for multi-region" : "一桁ミリ秒 NoSQL。DAX で μs 読み取り、グローバルテーブルで多地域"],
    redis: ["ElastiCache for Redis", en ? "Persistence, replication, Pub/Sub. For HA" : "永続・複製・Pub/Sub。高可用や複雑な構造に"],
    memcached: ["ElastiCache for Memcached", en ? "Multi-threaded simple cache. No persistence" : "マルチスレッドの単純キャッシュ。永続なし"],
    redshift: ["Amazon Redshift", en ? "Columnar MPP DWH for continuous analytics" : "列指向 MPP の DWH。継続的な大規模分析に"],
    athena: ["Amazon Athena", en ? "Serverless SQL on S3, scan-based pricing" : "S3 をサーバーレス SQL で分析、スキャン量課金"],
  };
  return <DecisionWidget lang={lang} steps={steps} leaves={leaves} />;
}

function DomainBars({ lang }) {
  const [sel, setSel] = useState(null);
  return (
    <div>
      {DOMAINS.map(d => (
        <div key={d.id} onClick={() => setSel(sel === d.id ? null : d.id)} style={{ marginBottom: 10, cursor: "pointer" }}>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 3 }}>
            <span><span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>{domName(d.id, lang)}</span>
            <strong>{d.pct}%</strong>
          </div>
          <div style={{ background: C.light, borderRadius: 6, height: 16, overflow: "hidden", border: sel === d.id ? `2px solid ${C.deep}` : "none" }}>
            <div style={{ width: `${d.pct / 30 * 100}%`, height: "100%", background: d.hue, display: "flex", alignItems: "center", paddingLeft: 6, color: "#fff", fontSize: 10, fontWeight: 700 }}>{d.pct}%</div>
          </div>
        </div>
      ))}
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 6 }}>{lang === "en" ? "→ Security (D1) has the largest weight (30%)." : "→ セキュリティ（D1）が最大比率（30%）。最優先で配分を。"}</div>
    </div>
  );
}

// ===== 決定木（コンピュート） =====
function ComputeTree({ lang }) {
  const en = lang === "en";
  const steps = {
    start: { q: en ? "Compute style?" : "コンピュートの形態は？", opts: [[en ? "VM (EC2)" : "仮想マシン（EC2）", "ec2"], [en ? "Containers" : "コンテナ", "container"], [en ? "Event-driven / serverless" : "イベント駆動・サーバーレス", "lambda"]] },
    ec2: { q: en ? "Workload pattern?" : "ワークロード特性は？", opts: [[en ? "Steady 24/7" : "常時稼働", "ri"], [en ? "Spiky / short-term" : "変動・短期", "od"], [en ? "Interruptible batch" : "中断可能なバッチ", "spot"]] },
    container: { q: en ? "Need Kubernetes?" : "Kubernetes が必要？", opts: [[en ? "Yes (k8s)" : "必要（k8s）", "eks"], [en ? "No, AWS-native" : "不要、AWS ネイティブ", "ecs"], [en ? "No server mgmt" : "サーバー管理したくない", "fargate"]] },
  };
  const leaves = {
    ri: ["RI / Savings Plans", en ? "Commit for steady baseline, up to ~72% off" : "常時稼働のベースラインを長期コミットで最大約 72% 割引"],
    od: ["On-Demand", en ? "Flexible, no commitment, for short/spiky use" : "コミット不要で柔軟、短期・変動負荷向け"],
    spot: ["Spot", en ? "Up to ~90% off for interruption-tolerant batch" : "中断耐性のあるバッチで最大約 90% 割引"],
    eks: ["Amazon EKS", en ? "Managed Kubernetes for portability" : "移植性重視のマネージド Kubernetes"],
    ecs: ["Amazon ECS", en ? "AWS-native orchestration, deeply integrated" : "AWS ネイティブで統合の深いオーケストレーション"],
    fargate: ["AWS Fargate", en ? "Serverless containers, per-task billing" : "サーバーレスでタスク単位課金、ノード管理不要"],
    lambda: ["AWS Lambda", en ? "Event-driven, auto-scale, pay per execution" : "イベント駆動・自動スケール・実行分のみ課金"],
  };
  return <DecisionWidget lang={lang} steps={steps} leaves={leaves} />;
}

// ===== 階層関係：Organizations =====
function OrgHierarchy({ lang }) {
  const en = lang === "en";
  const Node = ({ label, sub, hue, indent }) => (
    <div style={{ marginLeft: indent * 22, marginBottom: 8, position: "relative" }}>
      {indent > 0 && <span style={{ position: "absolute", left: -14, top: 0, bottom: 0, width: 2, background: C.mid }} />}
      <div style={{ background: hue, color: "#fff", borderRadius: 9, padding: "9px 13px", display: "inline-block", minWidth: 180 }}>
        <div style={{ fontWeight: 700, fontSize: 13 }}>{label}</div>
        <div style={{ fontSize: 11, opacity: 0.9 }}>{sub}</div>
      </div>
    </div>
  );
  return (
    <div>
      <Node label={en ? "Management Account" : "管理アカウント"} sub={en ? "Root of the organization" : "組織のルート・一括請求"} hue={C.deep} indent={0} />
      <Node label="Root" sub={en ? "Top of OU tree" : "OU ツリーの最上位"} hue={C.accent} indent={1} />
      <Node label={en ? "OU: Production" : "OU：本番"} sub={en ? "SCP applies here" : "SCP を適用"} hue="#CC7000" indent={2} />
      <Node label={en ? "Account A / B" : "アカウント A / B"} sub={en ? "Max perms capped by SCP" : "最大権限は SCP で制限"} hue={C.primary} indent={3} />
      <Node label={en ? "OU: Sandbox" : "OU：サンドボックス"} sub={en ? "Looser guardrails" : "緩いガードレール"} hue="#CC7000" indent={2} />
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8, lineHeight: 1.6 }}>
        {en ? "SCPs flow down the tree, capping the maximum permissions of every account below." : "SCP はツリーを下方向に流れ、配下の全アカウントの最大権限を制限します（権限の付与はしません）。"}
      </div>
    </div>
  );
}

// ===== 階層関係：IAM 権限スコープ =====
function IamScopeHierarchy({ lang }) {
  const en = lang === "en";
  const rings = [
    [en ? "SCP (organization cap)" : "SCP（組織の上限）", C.deep, en ? "Caps the account's max permissions" : "アカウントの最大権限を制限"],
    [en ? "Permissions boundary" : "許可境界", C.accent, en ? "Caps an individual principal" : "個別主体の上限を制限"],
    [en ? "Identity-based policy" : "アイデンティティベースポリシー", "#CC7000", en ? "Grants permissions to the principal" : "主体に権限を付与"],
    [en ? "Session policy" : "セッションポリシー", C.primary, en ? "Further narrows a single session" : "セッションを更に限定"],
  ];
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 10 }}>
        {en ? "Effective permissions = intersection of all caps AND an explicit allow, with any explicit deny winning." : "実効権限 = すべての上限の積集合 ∩ 明示的許可。明示的拒否があれば最優先で覆りません。"}
      </div>
      {rings.map(([label, hue, desc], i) => (
        <div key={i} style={{ marginLeft: i * 16, marginBottom: 7, background: "#fff", border: `2px solid ${hue}`, borderRadius: 10, padding: "9px 12px" }}>
          <span style={{ background: hue, color: "#fff", borderRadius: 5, padding: "2px 8px", fontSize: 11, fontWeight: 700, marginRight: 8 }}>{i + 1}</span>
          <strong style={{ fontSize: 13, color: C.deep }}>{label}</strong>
          <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 3 }}>{desc}</div>
        </div>
      ))}
    </div>
  );
}

// ===== 上下関係：多層防御レイヤー =====
function DefenseLayers({ lang }) {
  const en = lang === "en";
  const [sel, setSel] = useState(null);
  const layers = [
    [en ? "Edge: Shield + WAF + CloudFront" : "エッジ：Shield + WAF + CloudFront", "#232F3E", en ? "Mitigate DDoS and block L7 attacks before they reach the app." : "DDoS を緩和し L7 攻撃をアプリ到達前に遮断。"],
    [en ? "Network ACL (subnet)" : "ネットワーク ACL（サブネット）", "#146EB4", en ? "Stateless allow/deny at the subnet boundary." : "サブネット境界でステートレスに許可/拒否。"],
    [en ? "Security Group (instance)" : "セキュリティグループ（インスタンス）", "#CC7000", en ? "Stateful allow-only rules at the ENI." : "ENI 単位でステートフルな許可ルール。"],
    [en ? "IAM + encryption (data)" : "IAM＋暗号化（データ）", "#FF9900", en ? "Least-privilege access and encryption at rest/in transit." : "最小権限と保管時/転送時の暗号化。"],
  ];
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 10 }}>{en ? "Outer to inner: each layer backs up the others. Tap a layer." : "外側から内側へ、各層が互いを補完。層をタップ。"}</div>
      {layers.map(([label, hue, desc], i) => (
        <div key={i} onClick={() => setSel(sel === i ? null : i)}
          style={{ marginBottom: 6, marginLeft: i * 14, marginRight: i * 14, background: hue, color: "#fff", borderRadius: 10, padding: "12px 14px", cursor: "pointer", textAlign: "center", boxShadow: sel === i ? "0 0 0 3px rgba(255,153,0,.4)" : "none" }}>
          <div style={{ fontWeight: 700, fontSize: 13 }}>{label}</div>
          {sel === i && <div style={{ fontSize: 12, marginTop: 6, opacity: 0.95, lineHeight: 1.5 }}>{desc}</div>}
        </div>
      ))}
      <div style={{ textAlign: "center", fontSize: 11, color: "#9b8d82", marginTop: 4 }}>↓ {en ? "deeper = closer to data" : "下ほどデータに近い"}</div>
    </div>
  );
}

// ===== 上下関係：DR の RTO 階段 =====
function DrLadder({ lang }) {
  const en = lang === "en";
  const steps = [
    [en ? "Multi-Site (active/active)" : "マルチサイト（アクティブ/アクティブ）", en ? "Near-zero RTO, highest cost" : "RTO ほぼゼロ・最高コスト", "#232F3E"],
    [en ? "Warm Standby" : "ウォームスタンバイ", en ? "Scaled-down always-on, short RTO" : "縮小版を常時稼働・短い RTO", "#146EB4"],
    [en ? "Pilot Light" : "パイロットライト", en ? "Core (DB) only running" : "中核（DB）のみ稼働", "#CC7000"],
    [en ? "Backup & Restore" : "バックアップ＆リストア", en ? "Cheapest, largest RTO/RPO" : "最安・RTO/RPO 最大", "#FF9900"],
  ];
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "#9b8d82", marginBottom: 8 }}>
        <span>← {en ? "lower cost" : "低コスト"}</span><span>{en ? "shorter RTO" : "短い RTO"} →</span>
      </div>
      {steps.map(([label, sub, hue], i) => (
        <div key={i} style={{ marginBottom: 6, marginLeft: (3 - i) * 30, background: hue, color: "#fff", borderRadius: 9, padding: "10px 14px" }}>
          <div style={{ fontWeight: 700, fontSize: 13 }}>{label}</div>
          <div style={{ fontSize: 11.5, opacity: 0.9 }}>{sub}</div>
        </div>
      ))}
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8 }}>{en ? "Higher steps = shorter RTO but higher cost. Pick by RTO/RPO requirement and budget." : "上の段ほど RTO が短いがコストも高い。RTO/RPO 要件と予算で選ぶ。"}</div>
    </div>
  );
}

// ===== 並列関係：ストレージ =====
function StorageParallel({ lang }) {
  const en = lang === "en";
  const cards = [
    ["Amazon EBS", "#232F3E", [en ? "Block, single AZ" : "ブロック・単一 AZ", en ? "1 instance (usually)" : "原則 1 インスタンス", en ? "Persistent" : "永続"]],
    ["Amazon EFS", "#146EB4", [en ? "File (NFS), multi-AZ" : "ファイル(NFS)・複数 AZ", en ? "Many concurrent" : "多数で同時共有", en ? "Auto-scaling" : "自動拡張"]],
    [en ? "Instance Store" : "インスタンスストア", "#CC7000", [en ? "Block, ephemeral" : "ブロック・一時", en ? "Ultra fast" : "超高速", en ? "Lost on stop" : "停止で消失"]],
    ["Amazon S3", "#FF9900", [en ? "Object, 11x9 durability" : "オブジェクト・高耐久", en ? "Internet-scale" : "ほぼ無制限", en ? "Class by access" : "クラスで最適化"]],
  ];
  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
      {cards.map(([name, hue, items], i) => (
        <div key={i} style={{ border: `1.5px solid ${hue}`, borderRadius: 11, overflow: "hidden" }}>
          <div style={{ background: hue, color: "#fff", padding: "8px 10px", fontWeight: 700, fontSize: 13 }}>{name}</div>
          <div style={{ padding: "8px 10px" }}>
            {items.map((it, j) => <div key={j} style={{ fontSize: 12, color: C.ink, padding: "3px 0", lineHeight: 1.4 }}>・{it}</div>)}
          </div>
        </div>
      ))}
    </div>
  );
}

// ===== 並列関係：メッセージング =====
function MsgParallel({ lang }) {
  const en = lang === "en";
  const cards = [
    ["SQS", "#232F3E", en ? "Queue (pull)" : "キュー（プル）", en ? "One consumer pulls and processes. Buffers spikes." : "1 つのコンシューマーが取得し処理。急増を吸収。"],
    ["SNS", "#146EB4", en ? "Pub/Sub (push)" : "Pub/Sub（プッシュ）", en ? "Broadcasts one message to many subscribers." : "1 件を複数の購読先へ同報。"],
    ["EventBridge", "#FF9900", en ? "Event bus" : "イベントバス", en ? "Routes events by rules to many targets; SaaS integration." : "ルールで複数ターゲットへ振り分け。SaaS 連携。"],
  ];
  return (
    <div>
      {cards.map(([name, hue, kind, desc], i) => (
        <div key={i} style={{ display: "flex", alignItems: "stretch", marginBottom: 8, border: `1.5px solid ${hue}`, borderRadius: 11, overflow: "hidden" }}>
          <div style={{ background: hue, color: "#fff", padding: "10px 12px", fontWeight: 700, fontSize: 14, minWidth: 110, display: "flex", flexDirection: "column", justifyContent: "center" }}>
            {name}<span style={{ fontSize: 11, opacity: 0.9, fontWeight: 500 }}>{kind}</span>
          </div>
          <div style={{ padding: "10px 12px", fontSize: 12.5, color: C.ink, lineHeight: 1.5, display: "flex", alignItems: "center" }}>{desc}</div>
        </div>
      ))}
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 4 }}>{en ? "Common fan-out: SNS → multiple SQS queues for independent, scalable consumers." : "定番のファンアウト：SNS → 複数 SQS で独立・スケール可能な消費者を構成。"}</div>
    </div>
  );
}

// ===== フロー：3 層 Web リクエスト =====
function FlowChain({ nodes }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 0 }}>
      {nodes.map((n, i) => (
        <div key={i}>
          <div style={{ background: n[1], color: "#fff", borderRadius: 9, padding: "10px 13px" }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>{n[0]}</div>
            {n[2] && <div style={{ fontSize: 11.5, opacity: 0.92, marginTop: 2 }}>{n[2]}</div>}
          </div>
          {i < nodes.length - 1 && <div style={{ textAlign: "center", color: C.mid, fontSize: 18, lineHeight: "20px" }}>↓</div>}
        </div>
      ))}
    </div>
  );
}

function RequestFlow({ lang }) {
  const en = lang === "en";
  return (
    <div>
      <FlowChain nodes={[
        [en ? "User" : "ユーザー", "#9b8d82", en ? "Browser request" : "ブラウザからの要求"],
        ["Route 53", "#232F3E", en ? "DNS resolves to CloudFront/ALB" : "DNS で CloudFront/ALB へ解決"],
        ["CloudFront (+WAF)", "#146EB4", en ? "Edge cache, blocks L7 attacks" : "エッジキャッシュ・L7 攻撃を遮断"],
        ["ALB", "#CC7000", en ? "L7 routing to healthy targets" : "正常ターゲットへ L7 振り分け"],
        [en ? "EC2 ASG (web/app)" : "EC2 ASG（Web/アプリ）", "#FF9900", en ? "Auto-scales across AZs" : "複数 AZ で自動スケール"],
        [en ? "RDS Multi-AZ / cache" : "RDS マルチ AZ / キャッシュ", "#2E7D5B", en ? "DB in private subnet + ElastiCache" : "プライベートサブネットの DB＋ElastiCache"],
      ]} />
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8 }}>{en ? "Classic highly-available 3-tier flow. Each hop adds scaling or protection." : "高可用な 3 層構成の典型フロー。各段でスケールや防御を付加。"}</div>
    </div>
  );
}

function QueueFlow({ lang }) {
  const en = lang === "en";
  return (
    <div>
      <FlowChain nodes={[
        [en ? "Producer (API)" : "プロデューサー（API）", "#232F3E", en ? "Accepts requests fast, returns immediately" : "要求を素早く受け即応答"],
        ["Amazon SQS", "#146EB4", en ? "Buffers and persists messages" : "メッセージを蓄積・永続化"],
        [en ? "Worker ASG" : "ワーカー ASG", "#CC7000", en ? "Scales on queue length (idempotent)" : "キュー長でスケール（冪等処理）"],
        [en ? "Downstream DB" : "下流 DB", "#FF9900", en ? "Protected from spikes" : "急増から保護される"],
      ]} />
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8 }}>{en ? "Decoupling with a queue smooths spikes and isolates failures." : "キューによる疎結合で急増を平準化し障害を分離する。"}</div>
    </div>
  );
}

function FailoverFlow({ lang }) {
  const en = lang === "en";
  const [step, setStep] = useState(0);
  const frames = [
    [en ? "Normal: app → primary (AZ-a)" : "通常時：アプリ → プライマリ（AZ-a）", en ? "Synchronous replication to standby in AZ-b." : "AZ-b のスタンバイへ同期複製。", "#2E7D5B"],
    [en ? "Failure: primary in AZ-a goes down" : "障害発生：AZ-a のプライマリが停止", en ? "RDS detects the failure automatically." : "RDS が障害を自動検知。", "#C0392B"],
    [en ? "Failover: standby promoted (AZ-b)" : "フェイルオーバー：スタンバイ昇格（AZ-b）", en ? "Same endpoint (DNS) now points to AZ-b." : "同一エンドポイント（DNS）が AZ-b を指す。", "#CC7000"],
    [en ? "Recovered: app reconnects, continues" : "復旧：アプリは再接続し継続", en ? "App just needs retry logic; no manual change." : "アプリは再試行のみで手動変更は不要。", "#2E7D5B"],
  ];
  return (
    <div>
      <div style={{ background: frames[step][2], color: "#fff", borderRadius: 11, padding: 16, marginBottom: 10, minHeight: 70 }}>
        <div style={{ fontSize: 11, opacity: 0.85, fontWeight: 700 }}>STEP {step + 1} / 4</div>
        <div style={{ fontSize: 15, fontWeight: 800, margin: "4px 0" }}>{frames[step][0]}</div>
        <div style={{ fontSize: 12.5, opacity: 0.95, lineHeight: 1.5 }}>{frames[step][1]}</div>
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <button onClick={() => setStep(s => Math.max(0, s - 1))} disabled={step === 0}
          style={{ flex: 1, padding: 10, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: step === 0 ? "#bcae9f" : C.ink, fontWeight: 700, fontSize: 13, cursor: step === 0 ? "default" : "pointer" }}>← {en ? "Prev" : "前へ"}</button>
        <button onClick={() => setStep(s => Math.min(3, s + 1))} disabled={step === 3}
          style={{ flex: 1, padding: 10, borderRadius: 9, border: "none", background: step === 3 ? C.mid : C.primary, color: C.deep, fontWeight: 700, fontSize: 13, cursor: step === 3 ? "default" : "pointer" }}>{en ? "Next" : "次へ"} →</button>
      </div>
      <div style={{ display: "flex", gap: 5, marginTop: 10, justifyContent: "center" }}>
        {frames.map((_, i) => <div key={i} onClick={() => setStep(i)} style={{ width: 10, height: 10, borderRadius: 5, background: i === step ? C.primary : C.mid, cursor: "pointer" }} />)}
      </div>
    </div>
  );
}

// ===== 概念図：VPC =====
function VpcConcept({ lang }) {
  const en = lang === "en";
  const Box = ({ label, sub, hue, children, dashed }) => (
    <div style={{ border: `${dashed ? "2px dashed" : "1.5px solid"} ${hue}`, borderRadius: 10, padding: 10, marginBottom: 8 }}>
      <div style={{ fontWeight: 700, fontSize: 12.5, color: hue }}>{label}{sub && <span style={{ fontSize: 11, color: "#9b8d82", fontWeight: 500 }}> — {sub}</span>}</div>
      {children && <div style={{ marginTop: 8 }}>{children}</div>}
    </div>
  );
  const Chip = ({ t, hue }) => <span style={{ display: "inline-block", background: hue, color: "#fff", borderRadius: 6, padding: "4px 9px", fontSize: 11.5, fontWeight: 600, margin: "0 6px 6px 0" }}>{t}</span>;
  return (
    <div>
      <Box label="VPC (10.0.0.0/16)" sub={en ? "isolated network" : "隔離ネットワーク"} hue={C.deep}>
        <Box label={en ? "Public subnet" : "パブリックサブネット"} sub={en ? "route to IGW" : "IGW への経路あり"} hue={C.accent}>
          <Chip t="ALB" hue={C.accent} /><Chip t="NAT GW" hue={C.accent} /><Chip t={en ? "Bastion (rare)" : "踏み台(まれ)"} hue={C.accent} />
        </Box>
        <Box label={en ? "Private subnet" : "プライベートサブネット"} sub={en ? "no inbound from internet" : "インターネットから受信不可"} hue="#CC7000">
          <Chip t={en ? "App EC2 (ASG)" : "アプリ EC2(ASG)"} hue="#CC7000" /><Chip t="Lambda" hue="#CC7000" />
        </Box>
        <Box label={en ? "Private (DB) subnet" : "プライベート(DB)サブネット"} sub={en ? "most protected" : "最も保護"} hue={C.primary}>
          <Chip t={en ? "RDS Multi-AZ" : "RDS マルチ AZ"} hue={C.primary} /><Chip t="ElastiCache" hue={C.primary} />
        </Box>
        <Box label={en ? "Gateway endpoint" : "ゲートウェイエンドポイント"} sub={en ? "free private path to S3/DynamoDB" : "S3/DynamoDB へ無料の閉域経路"} hue="#2E7D5B" dashed />
      </Box>
      <div style={{ fontSize: 12, color: "#6b5d52", lineHeight: 1.6 }}>
        {en ? "Public subnet = has a route to the Internet Gateway. Private subnets reach the internet only outbound via NAT, and reach S3/DynamoDB free via a gateway endpoint." : "パブリック＝IGW への経路あり。プライベートは NAT 経由で外向きのみ、S3/DynamoDB へはゲートウェイエンドポイントで無料の閉域接続。"}
      </div>
    </div>
  );
}

// ===== 概念図：エッジ防御 =====
function EdgeConcept({ lang }) {
  const en = lang === "en";
  const items = [
    [en ? "Internet (users + attackers)" : "インターネット（利用者＋攻撃者）", "#9b8d82"],
    ["Route 53", "#232F3E", en ? "DNS + health-based failover" : "DNS＋ヘルスチェックで切替"],
    ["AWS Shield", "#146EB4", en ? "L3/L4 DDoS mitigation" : "L3/L4 の DDoS 緩和"],
    ["AWS WAF", "#CC7000", en ? "L7: blocks SQLi / XSS / rate" : "L7：SQLi/XSS/レート遮断"],
    ["CloudFront (+OAC)", "#FF9900", en ? "Edge cache, keeps origin private" : "エッジキャッシュ・オリジン非公開"],
    [en ? "Origin (S3 / ALB)" : "オリジン（S3 / ALB）", "#2E7D5B", en ? "Only reachable via CloudFront" : "CloudFront 経由のみ到達可"],
  ];
  return (
    <div>
      {items.map((it, i) => (
        <div key={i}>
          <div style={{ background: it[1], color: "#fff", borderRadius: 9, padding: "10px 13px", textAlign: "center" }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>{it[0]}</div>
            {it[2] && <div style={{ fontSize: 11.5, opacity: 0.92, marginTop: 2 }}>{it[2]}</div>}
          </div>
          {i < items.length - 1 && <div style={{ textAlign: "center", color: C.mid, fontSize: 16 }}>↓</div>}
        </div>
      ))}
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8 }}>{en ? "Layered edge: Shield (DDoS) → WAF (app attacks) → CloudFront (cache + OAC) protects the origin." : "層状のエッジ防御：Shield(DDoS)→WAF(アプリ攻撃)→CloudFront(キャッシュ＋OAC)でオリジンを守る。"}</div>
    </div>
  );
}

// ===== 決定木：オンプレ接続 =====
function ConnectTree({ lang }) {
  const en = lang === "en";
  const steps = {
    start: { q: en ? "Top priority?" : "最優先事項は？", opts: [[en ? "Stable bandwidth / low latency" : "安定帯域・低遅延", "dx"], [en ? "Low cost / quick setup" : "低コスト・手早く", "vpn"], [en ? "Stable + encrypted" : "安定かつ暗号化", "both"], [en ? "Connect many VPCs centrally" : "多数の VPC を集約", "tgw"]] },
  };
  const leaves = {
    dx: ["Direct Connect", en ? "Dedicated line: stable bandwidth and low latency. Higher cost." : "専用線で安定帯域・低遅延。コストは高め。"],
    vpn: ["Site-to-Site VPN", en ? "IPsec over internet: cheap and quick, best-effort quality." : "インターネット経由 IPsec で安価・手早い。品質はベストエフォート。"],
    both: ["Direct Connect + VPN", en ? "Stable DX path with an encrypted VPN on top." : "DX で安定帯域を確保し VPN を重ねて暗号化。"],
    tgw: ["Transit Gateway", en ? "Central hub aggregating many VPCs and on-prem connections." : "多数の VPC とオンプレ接続を集約する中央ハブ。"],
  };
  return <DecisionWidget lang={lang} steps={steps} leaves={leaves} />;
}

// ===== 決定木：ロードバランサー =====
function LbTree({ lang }) {
  const en = lang === "en";
  const steps = {
    start: { q: en ? "Traffic type?" : "トラフィックの種類は？", opts: [[en ? "HTTP/HTTPS (L7)" : "HTTP/HTTPS（L7）", "alb"], [en ? "TCP/UDP, ultra-low latency (L4)" : "TCP/UDP・超低遅延（L4）", "nlb"], [en ? "3rd-party appliances" : "サードパーティ仮想アプライアンス", "glb"]] },
  };
  const leaves = {
    alb: ["Application Load Balancer", en ? "L7 path/host routing for HTTP(S), microservices, WAF integration." : "L7 でパス/ホスト振り分け。マイクロサービスや WAF 連携に。"],
    nlb: ["Network Load Balancer", en ? "L4, static IP, millions of connections at ultra-low latency." : "L4・固定 IP・超低遅延で大量接続を処理。"],
    glb: ["Gateway Load Balancer", en ? "Deploy and scale third-party virtual appliances (firewalls, IDS)." : "FW/IDS 等のサードパーティ仮想アプライアンスを集約・スケール。"],
  };
  return <DecisionWidget lang={lang} steps={steps} leaves={leaves} />;
}

