function CachingLayers({ lang }) {
  const en = lang === "en";
  const [sel, setSel] = useState(null);
  const layers = [
    [en ? "CloudFront (edge)" : "CloudFront（エッジ）", "#232F3E", en ? "Caches static/dynamic content near users." : "利用者に近いエッジで静的/動的をキャッシュ。"],
    [en ? "API / app cache" : "API・アプリキャッシュ", "#146EB4", en ? "ElastiCache stores frequent query results." : "ElastiCache で頻出クエリ結果を保持。"],
    [en ? "DB accelerator" : "DB アクセラレータ", "#CC7000", en ? "DAX gives DynamoDB microsecond reads." : "DAX が DynamoDB をマイクロ秒読み取りに。"],
    [en ? "Database (source of truth)" : "データベース（真実の源）", "#FF9900", en ? "Hit only on cache miss; protected from load." : "ミス時のみ到達し負荷から保護される。"],
  ];
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 10 }}>{en ? "Closer to the user = faster & cheaper to serve. Tap a layer." : "利用者に近いほど高速・低コスト。層をタップ。"}</div>
      {layers.map(([label, hue, desc], i) => (
        <div key={i} onClick={() => setSel(sel === i ? null : i)}
          style={{ marginBottom: 6, marginLeft: i * 16, background: hue, color: "#fff", borderRadius: 10, padding: "11px 14px", cursor: "pointer", boxShadow: sel === i ? "0 0 0 3px rgba(255,153,0,.4)" : "none" }}>
          <div style={{ fontWeight: 700, fontSize: 13 }}>{label}</div>
          {sel === i && <div style={{ fontSize: 12, marginTop: 5, opacity: 0.95, lineHeight: 1.5 }}>{desc}</div>}
        </div>
      ))}
    </div>
  );
}

