const CASE_LABELS = {
  ja: { 1: "セット1（基礎シナリオ）", 2: "セット2（業務・データ）", 3: "セット3（設計・運用）", 4: "セット4（組織・推進）", 5: "セット5（総合）" },
  en: { 1: "Set 1 (Basics)", 2: "Set 2 (Process & Data)", 3: "Set 3 (Design & Ops)", 4: "Set 4 (Org & Rollout)", 5: "Set 5 (Comprehensive)" },
};
const CASE_PLAN = { D1: 6, D2: 7, D3: 7, D4: 7, D5: 4, D6: 4 };

function pickCase(row, rowEn, lang, seq) {
  const r = (lang === "en" && rowEn) ? rowEn : row;
  const rawOpts = r[2].map(o => ({ label: o[0], ok: o[1], fb: o[2] }));
  const correct = rawOpts.find(o => o.ok);
  const wrongs = rawOpts.filter(o => !o.ok);
  const base = correct ? [correct, ...wrongs] : rawOpts;
  const targetPos = ((seq || 0) * 3 + 1) % base.length;
  const order = [];
  let wi = 1;
  for (let p = 0; p < base.length; p++) {
    if (p === targetPos) order.push(0);
    else order.push(wi++);
  }
  const options = order.map(k => base[k]);
  return { scene: r[0], q: r[1], options, axis: r[3], point: r[4] };
}

function normReviewExam(rawQ) {
  const mk = (side, a) => ({
    scene: "",
    q: side.q,
    options: side.o.map((label, i) => ({ label, ok: i === a, fb: side.e })),
  });
  return {
    key: rawQ.ja.q + "|",
    ja: mk(rawQ.ja, rawQ.a),
    en: mk(rawQ.en, rawQ.a),
  };
}
function normReviewCase(cJa, cEn) {
  return {
    key: cJa.q + "|" + cJa.scene,
    ja: { scene: cJa.scene, q: cJa.q, options: cJa.options },
    en: cEn ? { scene: cEn.scene, q: cEn.q, options: cEn.options } : { scene: cJa.scene, q: cJa.q, options: cJa.options },
  };
}

function buildCaseSet(setNo) {
  const out = [];
  Object.entries(CASE_PLAN).forEach(([dom, n]) => {
    const pool = CASE_POOL[dom] || [];
    const poolEn = CASE_POOL_EN[dom] || [];
    if (pool.length === 0) return;
    for (let i = 0; i < n; i++) {
      const idx = ((setNo - 1) * 4 + i) % pool.length;
      const row = pool[idx];
      if (!row || !Array.isArray(row[2])) continue;
      out.push({ d: dom, ja: row, en: poolEn[idx] || null });
    }
  });
  return out;
}
const CASE_SETS = { 1: buildCaseSet(1), 2: buildCaseSet(2), 3: buildCaseSet(3), 4: buildCaseSet(4), 5: buildCaseSet(5) };

const FULL_BANK = (() => {
  const out = [];
  const seen = new Set();
  const push = (item) => {
    if (seen.has(item.ja.q)) return;
    seen.add(item.ja.q);
    out.push(item);
  };
  Object.entries(EXAM_POOL).forEach(([dom, rows]) => {
    const en = EXAM_POOL_EN[dom];
    rows.forEach((r, idx) => {
      const re = en && en[idx] ? en[idx] : r;
      push({ d: dom, a: 0, ja: rowToQ(r), en: rowToQ(re) });
    });
  });
  Object.entries(QUIZ_EXTRA).forEach(([dom, rows]) => {
    const en = QUIZ_EXTRA_EN[dom];
    rows.forEach((r, idx) => {
      const re = en && en[idx] ? en[idx] : r;
      push({ d: dom, a: 0, ja: rowToQ(r), en: rowToQ(re) });
    });
  });
  const caseToQ = (row) => {
    const opts = row[2];
    const correct = opts.find((o) => o[1]) || opts[0];
    const wrongs = opts.filter((o) => !o[1]);
    const o = [correct[0]].concat(wrongs.map((w) => w[0]));
    while (o.length < 4) o.push("該当しない");
    return { o: o.slice(0, 4), e: correct[2], head: row[0] + " " + row[1] };
  };
  Object.entries(CASE_POOL).forEach(([dom, rows]) => {
    const en = CASE_POOL_EN[dom];
    rows.forEach((r, idx) => {
      if (!Array.isArray(r[2])) return;
      const jaB = caseToQ(r);
      const ja = { q: "【事例】" + jaB.head, o: jaB.o, e: jaB.e };
      let enQ = { q: ja.q, o: ja.o, e: ja.e };
      const re = en && en[idx] ? en[idx] : null;
      if (re && Array.isArray(re[2])) {
        const enB = caseToQ(re);
        enQ = { q: "[Case] " + enB.head, o: enB.o, e: enB.e };
      }
      push({ d: dom, a: 0, ja: ja, en: enQ });
    });
  });
  return out;
})();

const TARGET = 500;
function ensureCount(list, target) {
  const r = [...list];
  if (r.length >= target) return r.slice(0, target);
  let i = 0;
  while (r.length < target) {
    const b = list[i % list.length];
    const sfx = `（${Math.floor(r.length / list.length) + 1}）`;
    r.push({ ...b, ja: { ...b.ja, q: b.ja.q + sfx }, en: { ...b.en, q: b.en.q + sfx } });
    i++;
  }
  return r;
}
const QUIZ_BANK = ensureCount(FULL_BANK, TARGET).map((q, i) => {
  const jaO = Array.isArray(q.ja.o) ? [...q.ja.o] : [];
  const enO = Array.isArray(q.en.o) ? [...q.en.o] : [...jaO];
  while (jaO.length < 4) jaO.push("");
  while (enO.length < 4) enO.push("");
  const targetPos = (i * 3 + 2) % 4;
  const order = rotateToPos(jaO, targetPos);
  const a = order.indexOf(q.a || 0);
  return {
    d: q.d, a: a < 0 ? 0 : a,
    ja: { q: q.ja.q, o: order.map(k => jaO[k]), e: q.ja.e },
    en: { q: q.en.q, o: order.map(k => enO[k]), e: q.en.e },
  };
});

