// クイズ全問題（BANK + BANK_EXTRA + BANK_EXTRA2 を結合）
const ALL_QUESTIONS = BANK.concat(BANK_EXTRA).concat(BANK_EXTRA2);

// ===== 永続化 =====
async function loadState() {
  try {
    const r = await window.storage.get(STORE_KEY);
    return r ? JSON.parse(r.value) : null;
  } catch { return null; }
}
async function saveState(s) {
  try { await window.storage.set(STORE_KEY, JSON.stringify(s)); } catch {}
}

function todayStr() { return new Date().toISOString().slice(0, 10); }
function domName(id) { return DOM_NAME[id]; }
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ===== 決定的シャッフル：選択肢の順序を入れ替え、正解が先頭固定にならないようにする =====
// 問題文から安定したシード値を生成（同じ問題は常に同じ並びになる＝学習の一貫性）
function hashString(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
// シード付き擬似乱数（mulberry32）
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
// 問題オブジェクトを受け取り、シャッフル済みの選択肢配列と新しい正解indexを返す
// 戻り値: { opts: [...], a: 新正解index }
function shuffleOptions(Q) {
  const rng = mulberry32(hashString(Q.q));
  // インデックス配列をFisher-Yatesでシャッフル
  const idx = Q.o.map((_, i) => i);
  for (let i = idx.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [idx[i], idx[j]] = [idx[j], idx[i]];
  }
  // 万一、正解がまだ先頭(0番目)に来てしまった場合は、別の位置と入れ替える
  let pos = idx.indexOf(Q.a);
  if (pos === 0) {
    // rngで0以外の位置を選んで交換
    const swapWith = 1 + Math.floor(rng() * (idx.length - 1));
    [idx[0], idx[swapWith]] = [idx[swapWith], idx[0]];
    pos = idx.indexOf(Q.a);
  }
  const opts = idx.map(i => Q.o[i]);
  return { opts, a: pos };
}

// ===== メインアプリ =====
function App() {
  const [tab, setTab] = useState("home");
  const [state, setState] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const t = T;

  useEffect(() => {
    loadState().then(s => {
      setState(s || { progress: {}, meta: { streak: 0, lastDay: "", dailyDay: "", dailyCount: 0 } });
      setLoaded(true);
    });
  }, []);

  const persist = (next) => { setState(next); saveState(next); };

  const record = (domId, correct) => {
    const next = JSON.parse(JSON.stringify(state));
    if (!next.progress[domId]) next.progress[domId] = { correct: 0, attempts: 0 };
    next.progress[domId].attempts++;
    if (correct) next.progress[domId].correct++;
    const today = todayStr();
    if (next.meta.dailyDay !== today) { next.meta.dailyDay = today; next.meta.dailyCount = 0; }
    next.meta.dailyCount++;
    if (next.meta.lastDay !== today) {
      const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
      next.meta.streak = next.meta.lastDay === yesterday ? next.meta.streak + 1 : 1;
      next.meta.lastDay = today;
    }
    persist(next);
  };

  if (!loaded) return <div style={{ padding: 40, textAlign: "center", color: C.deep }}>{t.loading}</div>;

  const TABS = [
    ["home", t.tabHome], ["quiz", t.tabQuiz], ["exam", t.tabExam], ["scenario", t.tabScenario],
    ["compare", t.tabCompare], ["diagram", t.tabDiagram], ["confuse", t.tabConfuse], ["glossary", t.tabGlossary],
  ];

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: C.ink, background: "#FAFEFF", minHeight: "100vh" }}>
      <div style={{ background: C.deep, color: "#fff", padding: "16px 18px" }}>
        <div style={{ fontSize: 19, fontWeight: 700 }}>{t.appTitle}</div>
        <div style={{ fontSize: 12, opacity: 0.85, marginTop: 2 }}>{t.appSub}</div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", borderBottom: `2px solid ${C.mid}`, background: C.light }}>
        {TABS.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)}
            style={{
              flex: "1 1 auto", padding: "11px 8px", border: "none", cursor: "pointer",
              background: tab === k ? "#fff" : "transparent",
              color: tab === k ? C.deep : C.ink, fontWeight: tab === k ? 700 : 500,
              fontSize: 13, borderBottom: tab === k ? `3px solid ${C.primary}` : "3px solid transparent",
            }}>
            {label}
          </button>
        ))}
      </div>
      <div style={{ padding: 16, maxWidth: 820, margin: "0 auto" }}>
        {tab === "home" && <Home state={state} t={t} />}
        {tab === "quiz" && <Quiz onAnswer={record} t={t} questions={ALL_QUESTIONS} />}
        {tab === "exam" && <Exam onAnswer={record} t={t} />}
        {tab === "scenario" && <Scenario t={t} />}
        {tab === "compare" && <Compare t={t} />}
        {tab === "diagram" && <Diagrams t={t} />}
        {tab === "confuse" && <Confuse t={t} />}
        {tab === "glossary" && <Glossary t={t} />}
      </div>
    </div>
  );
}

// ===== 進捗 =====
function Home({ state, t }) {
  const totals = useMemo(() => {
    let c = 0, a = 0;
    Object.values(state.progress).forEach(p => { c += p.correct; a += p.attempts; });
    return { c, a, rate: a ? Math.round((c / a) * 100) : 0 };
  }, [state]);

  const weak = useMemo(() => {
    return DOMAINS.map(d => {
      const p = state.progress[d.id] || { correct: 0, attempts: 0 };
      const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : null;
      return { ...d, rate, attempts: p.attempts };
    }).filter(d => d.attempts > 0).sort((a, b) => a.rate - b.rate);
  }, [state]);

  const dailyPct = Math.min(100, Math.round((state.meta.dailyCount / DAILY_GOAL) * 100));

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 16 }}>
        <Stat label={t.overallRate} value={`${totals.rate}%`} sub={`${totals.c}/${totals.a}${t.questionsUnit}`} color={totals.rate >= PASS ? C.ok : C.primary} />
        <Stat label={t.streak} value={`${state.meta.streak}日`} sub={t.streakSub} color={C.primary} />
      </div>

      <Card title={`${t.dailyGoal} (${state.meta.dailyCount}/${DAILY_GOAL})`}>
        <Bar pct={dailyPct} color={dailyPct >= 100 ? C.ok : C.primary} />
        <div style={{ fontSize: 12, marginTop: 6, color: "#5a7780" }}>
          {dailyPct >= 100 ? t.dailyDone : t.dailyRemain(DAILY_GOAL - state.meta.dailyCount)}
        </div>
      </Card>

      <Card title={t.domMastery}>
        {DOMAINS.map(d => {
          const p = state.progress[d.id] || { correct: 0, attempts: 0 };
          const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : 0;
          return (
            <div key={d.id} style={{ marginBottom: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span style={{ fontWeight: 600 }}>
                  <span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
                  {domName(d.id)}
                </span>
                <span style={{ color: "#5a7780" }}>{d.pct}% · {p.attempts ? `${rate}%` : t.notStarted}</span>
              </div>
              <Bar pct={rate} color={d.hue} faint={!p.attempts} />
            </div>
          );
        })}
      </Card>

      {weak.length > 0 && (
        <Card title={t.weakDomains}>
          {weak.slice(0, 3).map(d => (
            <div key={d.id} style={{ fontSize: 13, padding: "6px 0", borderBottom: `1px solid ${C.light}` }}>
              <span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
              {domName(d.id)} — <strong style={{ color: d.rate < PASS ? C.ng : C.ok }}>{d.rate}%</strong>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}

function Stat({ label, value, sub, color }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14 }}>
      <div style={{ fontSize: 11.5, color: "#5a7780" }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 800, color }}>{value}</div>
      <div style={{ fontSize: 11, color: "#86a6b0" }}>{sub}</div>
    </div>
  );
}
function Card({ title, children }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep, marginBottom: 10 }}>{title}</div>
      {children}
    </div>
  );
}
function Bar({ pct, color, faint }) {
  return (
    <div style={{ background: C.light, borderRadius: 8, height: 9, overflow: "hidden" }}>
      <div style={{ width: `${pct}%`, height: "100%", background: faint ? C.mid : color, transition: "width .3s" }} />
    </div>
  );
}

// ===== クイズ =====
function Quiz({ onAnswer, t, questions }) {
  const [filter, setFilter] = useState("ALL");
  const [pos, setPos] = useState(0);
  const [history, setHistory] = useState({}); // {globalIndex: selectedOption}
  const [stats, setStats] = useState({ c: 0, a: 0 });

  const pool = useMemo(() => {
    const idxs = filter === "ALL" ? questions.map((_, i) => i) : questions.map((_, i) => i).filter(i => questions[i].d === filter);
    return idxs; // 既定は固定順（収録順）
  }, [filter, questions]);

  useEffect(() => { setPos(0); setHistory({}); setStats({ c: 0, a: 0 }); }, [pool]);

  const total = pool.length;
  const qi = pool[pos];
  const Q = questions[qi];
  // 選択肢を決定的にシャッフル（正解が先頭固定にならない）
  const { opts, a: correctIdx } = useMemo(() => shuffleOptions(Q), [qi]);
  const sel = history[qi] ?? null;

  const choose = (i) => {
    if (sel !== null) return;
    setHistory(h => ({ ...h, [qi]: i }));
    const correct = i === correctIdx;
    setStats(s => ({ c: s.c + (correct ? 1 : 0), a: s.a + 1 }));
    onAnswer(Q.d, correct);
  };
  const next = () => { if (pos + 1 < total) setPos(p => p + 1); };
  const prev = () => { if (pos > 0) setPos(p => p - 1); };

  const rate = stats.a ? Math.round((stats.c / stats.a) * 100) : 0;

  return (
    <div>
      <div style={{ fontSize: 12.5, color: "#476770", marginBottom: 8 }}>全{total}問</div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
        {["ALL", ...DOMAINS.map(d => d.id)].map(k => (
          <button key={k} onClick={() => setFilter(k)}
            style={{
              padding: "5px 11px", borderRadius: 16, fontSize: 12, cursor: "pointer",
              border: `1px solid ${filter === k ? C.primary : C.mid}`,
              background: filter === k ? C.primary : "#fff", color: filter === k ? "#fff" : C.ink, fontWeight: 600,
            }}>
            {k === "ALL" ? t.allFields : k}
          </button>
        ))}
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={prev} disabled={pos === 0}
          style={{
            padding: "8px 14px", borderRadius: 9, fontSize: 12.5, fontWeight: 600,
            border: `1.5px solid ${pos === 0 ? C.mid : C.primary}`,
            background: "#fff", color: pos === 0 ? "#a8c2cc" : C.primary,
            cursor: pos === 0 ? "not-allowed" : "pointer",
          }}>
          ← 前の問題
        </button>
        <span style={{ fontSize: 13, color: "#5a7780", fontWeight: 600 }}>{pos + 1} / {total}</span>
      </div>

      {stats.a > 0 && (
        <div style={{ marginBottom: 10 }}>
          <div style={{ fontSize: 12, color: "#5a7780", marginBottom: 3 }}>
            {t.sessionRate} {rate}%（{stats.c}/{stats.a}）
          </div>
          <Bar pct={rate} color={rate >= PASS ? C.ok : C.ng} />
        </div>
      )}

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11, color: "#fff", background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>
          {Q.d} · {domName(Q.d)}
        </div>
        <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 14, lineHeight: 1.5 }}>{Q.q}</div>
        {opts.map((opt, i) => {
          let bg = "#fff", bd = C.mid, col = C.ink;
          if (sel !== null) {
            if (i === correctIdx) { bg = "#E4F6EC"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FBE9E7"; bd = C.ng; col = C.ng; }
          }
          return (
            <button key={i} onClick={() => choose(i)} disabled={sel !== null}
              style={{
                display: "block", width: "100%", textAlign: "left", marginBottom: 8,
                padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`,
                background: bg, color: col, cursor: sel === null ? "pointer" : "default",
                fontSize: 13.5, lineHeight: 1.4, fontWeight: sel !== null && i === correctIdx ? 700 : 500,
              }}>
              <span style={{ fontWeight: 700, marginRight: 8 }}>{"ABCD"[i]}</span>{opt}
            </button>
          );
        })}
        {sel !== null && (
          <div style={{ marginTop: 12 }}>
            <div style={{ background: C.light, borderRadius: 9, padding: 12, fontSize: 13, lineHeight: 1.55 }}>
              <strong style={{ color: sel === correctIdx ? C.ok : C.ng }}>{sel === correctIdx ? t.correct : t.incorrect}</strong>
              ・{t.answerIs("ABCD"[correctIdx])}{Q.e}
            </div>
            {pos + 1 < total && (
              <button onClick={next}
                style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
                {t.nextQ}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// ===== 模擬試験（演習モード / 本番モード）=====
function Exam({ onAnswer, t }) {
  const [mode, setMode] = useState("practice");
  const [setNo, setSetNo] = useState(null);
  const [phase, setPhase] = useState("select");
  const [pos, setPos] = useState(0);
  const [picks, setPicks] = useState({}); // {qIndex: selectedOption(シャッフル後index)}
  const [sel, setSel] = useState(null);

  const rawQs = setNo ? EXAM_SETS[setNo] : [];
  // 各問の選択肢を決定的シャッフル（セット固定でも並びは安定）
  const qs = useMemo(() => rawQs.map(Q => {
    const { opts, a } = shuffleOptions(Q);
    return { ...Q, o: opts, a };
  }), [setNo]);

  const start = (n) => { setSetNo(n); setPos(0); setPicks({}); setSel(null); setPhase("run"); };

  const choosePractice = (i) => {
    if (sel !== null) return;
    setSel(i);
    const Q = qs[pos];
    const correct = i === Q.a;
    onAnswer(Q.d, correct);
    setPicks(p => ({ ...p, [pos]: i }));
  };
  const chooseReal = (i) => { setPicks(p => ({ ...p, [pos]: i })); };

  const next = () => {
    if (mode === "practice") {
      setSel(null);
      if (pos + 1 >= qs.length) finishExam();
      else setPos(pos + 1);
    } else {
      if (pos + 1 >= qs.length) finishExam();
      else setPos(pos + 1);
    }
  };
  const prev = () => { if (pos > 0) { setPos(pos - 1); if (mode === "practice") setSel(picks[pos - 1] ?? null); } };

  const finishExam = () => {
    if (mode === "real") {
      qs.forEach((Q, i) => {
        if (picks[i] !== undefined) onAnswer(Q.d, picks[i] === Q.a);
      });
    }
    setPhase("result");
  };

  if (phase === "select") {
    return (
      <div>
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginBottom: 14 }}>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep, marginBottom: 8 }}>{t.examTitle}</div>
          <div style={{ fontSize: 13, lineHeight: 1.6, color: "#476770", marginBottom: 12, whiteSpace: "pre-line" }}>{t.examDesc}</div>
          <div style={{ display: "flex", background: C.light, borderRadius: 24, padding: 4 }}>
            {[["practice", t.modePractice], ["real", t.modeReal]].map(([m, label]) => (
              <button key={m} onClick={() => setMode(m)}
                style={{
                  flex: 1, border: "none", cursor: "pointer", borderRadius: 20, padding: "10px 8px",
                  fontSize: 13.5, fontWeight: 700,
                  background: mode === m ? "#fff" : "transparent",
                  color: mode === m ? C.deep : "#86a6b0",
                  boxShadow: mode === m ? "0 1px 4px rgba(11,110,143,.18)" : "none",
                  transition: "all .2s",
                }}>
                {label}
              </button>
            ))}
          </div>
        </div>

        {[1, 2, 3, 4, 5].map(n => (
          <button key={n} onClick={() => SET_READY[n] && start(n)} disabled={!SET_READY[n]}
            style={{
              width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${SET_READY[n] ? C.primary : C.mid}`,
              background: SET_READY[n] ? "#fff" : C.light, cursor: SET_READY[n] ? "pointer" : "not-allowed",
              display: "flex", justifyContent: "space-between", alignItems: "center",
            }}>
            <span>
              <span style={{ fontWeight: 700, fontSize: 15, color: SET_READY[n] ? C.deep : "#86a6b0" }}>{t.setLabel} {n}</span>
              <span style={{ fontSize: 12, color: "#86a6b0", marginLeft: 10 }}>50{t.questionsUnit}</span>
            </span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: SET_READY[n] ? C.primary : "#a8c2cc" }}>
              {SET_READY[n] ? `${mode === "practice" ? t.modePractice : t.modeReal}で${t.start}` : t.preparing}
            </span>
          </button>
        ))}
      </div>
    );
  }

  if (phase === "result") {
    const graded = qs.map((Q, i) => ({ q: Q, sel: picks[i] ?? null, correct: picks[i] === Q.a }));
    const answered = graded.filter(g => g.sel !== null);
    const c = graded.filter(g => g.correct).length;
    const rate = Math.round((c / qs.length) * 100);
    const passed = rate >= PASS;
    const byDom = DOMAINS.map(d => {
      const sub = graded.filter(g => g.q.d === d.id);
      const cc = sub.filter(g => g.correct).length;
      return { ...d, total: sub.length, correct: cc };
    }).filter(d => d.total > 0);
    const wrong = graded.filter(g => !g.correct);

    return (
      <div>
        <div style={{ background: passed ? "#E4F6EC" : "#FBE9E7", border: `2px solid ${passed ? C.ok : C.ng}`, borderRadius: 12, padding: 18, textAlign: "center", marginBottom: 14 }}>
          <div style={{ fontSize: 13, color: "#5a7780" }}>{t.setLabel}{setNo} · {mode === "practice" ? t.modePractice : t.modeReal} {t.result}</div>
          <div style={{ fontSize: 40, fontWeight: 800, color: passed ? C.ok : C.ng }}>{rate}%</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: passed ? C.ok : C.ng }}>{passed ? t.reachedPass : t.needMore(PASS - rate)}</div>
          <div style={{ fontSize: 12, color: "#5a7780", marginTop: 4 }}>{t.correctOf(c, qs.length)}{answered.length < qs.length ? `（${t.unanswered} ${qs.length - answered.length}）` : ""}</div>
        </div>

        <Card title={t.domBreakdown}>
          {byDom.map(d => (
            <div key={d.id} style={{ marginBottom: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span><span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>{domName(d.id)}</span>
                <strong style={{ color: d.correct / d.total >= PASS / 100 ? C.ok : C.ng }}>{d.correct}/{d.total}</strong>
              </div>
              <Bar pct={Math.round(d.correct / d.total * 100)} color={d.correct / d.total >= PASS / 100 ? C.ok : C.ng} />
            </div>
          ))}
        </Card>

        <Card title={t.wrongTitle(wrong.length)}>
          {wrong.length === 0 ? (
            <div style={{ fontSize: 13, color: C.ok }}>{t.allCorrect}</div>
          ) : wrong.map((a, idx) => (
            <div key={idx} style={{ padding: "8px 0", borderBottom: `1px solid ${C.light}`, fontSize: 13 }}>
              <div style={{ fontWeight: 600, marginBottom: 4 }}>
                <span style={{ background: DOM_HUE[a.q.d], color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 10.5, marginRight: 6 }}>{a.q.d}</span>
                {a.q.q}
              </div>
              <div style={{ color: C.ng, fontSize: 12.5 }}>{t.yourAnswer}：{a.sel !== null ? `${"ABCD"[a.sel]} ${a.q.o[a.sel]}` : "—"}</div>
              <div style={{ color: C.ok, fontSize: 12.5 }}>{t.answer}：{"ABCD"[a.q.a]} {a.q.o[a.q.a]}</div>
              <div style={{ color: "#476770", fontSize: 12.5, marginTop: 2 }}>{a.q.e}</div>
            </div>
          ))}
        </Card>

        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={() => start(setNo)} style={{ flex: 1, padding: 13, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.retrySet}</button>
          <button onClick={() => setPhase("select")} style={{ flex: 1, padding: 13, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.toSetSelect}</button>
        </div>
      </div>
    );
  }

  // 出題
  const Q = qs[pos];
  const opts = Q.o;
  const curPick = picks[pos] ?? null;
  const answeredCount = Object.keys(picks).length;
  const showFeedback = mode === "practice" && sel !== null;
  const isLast = pos + 1 >= qs.length;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8, fontSize: 12.5, color: "#5a7780" }}>
        <span>
          <span style={{ background: mode === "practice" ? C.primary : C.deep, color: "#fff", borderRadius: 4, padding: "1px 8px", fontSize: 11, fontWeight: 700, marginRight: 8 }}>
            {mode === "practice" ? t.modePractice : t.modeReal}
          </span>
          {t.setLabel}{setNo} · {t.questionNo(pos + 1, qs.length)}
        </span>
        <span>{t.answered} {answeredCount}/{qs.length}</span>
      </div>
      <Bar pct={Math.round(((pos + 1) / qs.length) * 100)} color={C.primary} />

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "12px 0 0" }}>
        <button onClick={prev} disabled={pos === 0}
          style={{
            padding: "8px 14px", borderRadius: 9, fontSize: 12.5, fontWeight: 600,
            border: `1.5px solid ${pos === 0 ? C.mid : C.primary}`,
            background: "#fff", color: pos === 0 ? "#a8c2cc" : C.primary,
            cursor: pos === 0 ? "not-allowed" : "pointer",
          }}>
          ← 前の問題
        </button>
        <span style={{ fontSize: 13, color: "#5a7780", fontWeight: 600 }}>{pos + 1} / {qs.length}</span>
      </div>

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginTop: 12 }}>
        <div style={{ fontSize: 11, color: "#fff", background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>
          {Q.d} · {domName(Q.d)}
        </div>
        <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 14, lineHeight: 1.5 }}>{Q.q}</div>
        {opts.map((opt, i) => {
          let bg = "#fff", bd = C.mid, col = C.ink;
          if (mode === "practice" && sel !== null) {
            if (i === Q.a) { bg = "#E4F6EC"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FBE9E7"; bd = C.ng; col = C.ng; }
          } else if (mode === "real" && curPick === i) {
            bg = C.light; bd = C.primary; col = C.deep;
          }
          const disabled = mode === "practice" && sel !== null;
          return (
            <button key={i} onClick={() => mode === "practice" ? choosePractice(i) : chooseReal(i)} disabled={disabled}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: disabled ? "default" : "pointer", fontSize: 13.5, lineHeight: 1.4, fontWeight: (mode === "practice" && sel !== null && i === Q.a) || (mode === "real" && curPick === i) ? 700 : 500 }}>
              <span style={{ fontWeight: 700, marginRight: 8 }}>{"ABCD"[i]}</span>{opt}
            </button>
          );
        })}

        {showFeedback && (
          <div style={{ marginTop: 12 }}>
            <div style={{ background: C.light, borderRadius: 9, padding: 12, fontSize: 13, lineHeight: 1.55 }}>
              <strong style={{ color: sel === Q.a ? C.ok : C.ng }}>{sel === Q.a ? t.correct : t.incorrect}</strong>
              ・{t.answerIs("ABCD"[Q.a])}{Q.e}
            </div>
            <button onClick={next} style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
              {isLast ? t.seeResult : t.nextQ}
            </button>
          </div>
        )}

        {mode === "real" && (
          <button onClick={next}
            style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: isLast ? C.deep : C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
            {isLast ? t.finish : t.nextQ}
          </button>
        )}
      </div>
    </div>
  );
}

// ===== 図解（インタラクティブ）=====
function Diagrams({ t }) {
  const [open, setOpen] = useState("domains");
  const Section = ({ id, title, children }) => (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, marginBottom: 12, overflow: "hidden" }}>
      <button onClick={() => setOpen(open === id ? "" : id)}
        style={{ width: "100%", textAlign: "left", padding: "13px 15px", border: "none", background: open === id ? C.light : "#fff", color: C.deep, fontWeight: 700, fontSize: 13.5, cursor: "pointer", display: "flex", justifyContent: "space-between" }}>
        <span>{title}</span><span>{open === id ? "−" : "+"}</span>
      </button>
      {open === id && <div style={{ padding: 15, borderTop: `1px solid ${C.light}` }}>{children}</div>}
    </div>
  );
  return (
    <div>
      <div style={{ fontSize: 12, color: "#86a6b0", marginBottom: 10 }}>{t.diagIntro}</div>
      <Section id="domains" title="① 5領域の出題比率"><DomainBars /></Section>
      <Section id="overview" title="② Power Platform 全体構成（タップで解説）"><Overview /></Section>
      <Section id="appchoice" title="③ アプリ形式の決定木（クイズ形式）"><AppDecision /></Section>
      <Section id="trigger" title="④ クラウドフローのトリガー（タップ）"><Triggers /></Section>
      <Section id="security" title="⑤ セキュリティの多層モデル（タップ）"><SecurityLadder /></Section>
      <Section id="roi" title="⑥ 自動化の削減効果シミュレータ"><RoiSim /></Section>
      <Section id="data" title="⑦ Dataverse のデータ構造（展開ツリー）"><InteractiveTree data={DV_TREE} /></Section>
      <Section id="admin" title="⑧ 管理階層（展開ツリー）"><InteractiveTree data={ADMIN_TREE} /></Section>
    </div>
  );
}

// ① 全体構成
function Overview() {
  const items = [
    ["Power Apps", "作る", "ローコードで業務アプリを構築(キャンバス/モデル駆動型)"],
    ["Power Automate", "自動化", "クラウドフローとRPAで繰り返し作業を自動化"],
    ["Power Pages", "公開する", "外部向けのセルフサービスWebサイトを構築"],
    ["Power BI", "見える化", "データを可視化・分析し意思決定を支援"],
    ["Dataverse", "データ基盤", "全サービス共通の安全なデータ基盤"],
    ["コネクタ", "つなぐ", "1,000以上の外部サービスをコードなしで接続"],
  ];
  const [sel, setSel] = useState(null);
  const colors = [C.deep, "#1A86A8", C.primary, "#3BB8D4", "#6CCBDE", "#8FD9E8"];
  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 10 }}>
        {items.map((it, i) => (
          <div key={i} onClick={() => setSel(sel === i ? null : i)}
            style={{ background: colors[i], color: "#fff", borderRadius: 9, padding: "12px 10px", cursor: "pointer", border: sel === i ? `3px solid ${C.ink}` : "3px solid transparent" }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>{it[0]}</div>
            <div style={{ fontSize: 11, opacity: 0.9 }}>{it[1]}</div>
          </div>
        ))}
      </div>
      {sel !== null ? (
        <div style={{ background: C.light, borderRadius: 9, padding: 12 }}>
          <div style={{ fontWeight: 700, color: C.deep, fontSize: 14 }}>{items[sel][0]}</div>
          <div style={{ fontSize: 13, marginTop: 4, lineHeight: 1.5 }}>{items[sel][2]}</div>
        </div>
      ) : (
        <div style={{ fontSize: 12.5, color: "#476770" }}>各タイルをタップ。Dataverseとコネクタが基盤、その上に4サービスが乗る。</div>
      )}
    </div>
  );
}

// ② アプリ形式の決定木
function AppDecision() {
  const steps = {
    start: { q: "利用者は誰か？", opts: [["社内の担当者", "internal"], ["外部の顧客", "pages"]] },
    internal: { q: "重視するのは？", opts: [["自由なデザイン・特定タスク", "canvas"], ["複雑なデータ・多数の表", "model"]] },
  };
  const leaves = {
    canvas: ["キャンバスアプリ", "デザイン主導で自由に配置。軽量・タスク特化のモバイルアプリに向く"],
    model: ["モデル駆動型アプリ", "データ主導でDataverseから自動生成。複雑なデータ管理に向く"],
    pages: ["Power Pages", "認証とWebロールを備えた外部向けセルフサービスサイト"],
  };
  const [path, setPath] = useState([]);
  const cur = path.length === 0 ? "start" : path[path.length - 1];
  const leaf = leaves[cur];
  return (
    <div>
      <div style={{ marginBottom: 10, fontSize: 12, color: "#86a6b0" }}>
        {path.length > 0 && <button onClick={() => setPath(p => p.slice(0, -1))} style={{ border: "none", background: "none", color: C.primary, cursor: "pointer", fontWeight: 700, padding: 0 }}>← 戻る</button>}
      </div>
      {!leaf && steps[cur] && (
        <div>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.deep, marginBottom: 12 }}>{steps[cur].q}</div>
          {steps[cur].opts.map(([label, to]) => (
            <button key={to} onClick={() => setPath(p => [...p, to])}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "12px 14px", borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ink, cursor: "pointer", fontSize: 14, fontWeight: 600 }}>
              {label} →
            </button>
          ))}
        </div>
      )}
      {leaf && (
        <div style={{ background: "#E4F6EC", border: `2px solid ${C.ok}`, borderRadius: 10, padding: 14 }}>
          <div style={{ fontSize: 11, color: C.ok, fontWeight: 700 }}>結論</div>
          <div style={{ fontSize: 16, fontWeight: 800, color: C.deep, margin: "4px 0" }}>{leaf[0]}</div>
          <div style={{ fontSize: 13, lineHeight: 1.5 }}>{leaf[1]}</div>
          <button onClick={() => setPath([])} style={{ marginTop: 12, padding: "8px 14px", borderRadius: 8, border: "none", background: C.primary, color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>最初から</button>
        </div>
      )}
    </div>
  );
}

// ③ トリガー
