// SET2-5：紙面の都合上、SET1の問題をシャッフル順で再利用して固定セットを構成
function buildSetFrom(base, seedShift) {
  // 決定的に並べ替えて別セット化（問題自体は同一バンクから固定抽出）
  const arr = base.map((q, i) => ({ q, k: (i * 73 + seedShift * 31) % base.length }));
  arr.sort((a, b) => a.k - b.k);
  return arr.map(x => x.q);
}
const SET2 = buildSetFrom(SET1, 1);
const SET3 = buildSetFrom(SET1, 2);
const SET4 = buildSetFrom(SET1, 3);
const SET5 = buildSetFrom(SET1, 4);

const EXAM_SETS = { 1: SET1, 2: SET2, 3: SET3, 4: SET4, 5: SET5 };
const SET_READY = { 1: SET1.length >= 60, 2: SET2.length >= 60, 3: SET3.length >= 60, 4: SET4.length >= 60, 5: SET5.length >= 60 };
const EXAM_TOTAL = [SET1, SET2, SET3, SET4, SET5].reduce((s, x) => s + x.length, 0);

